// Şu anki ders+konu+seviye filtresine giren soru listesi (render ile aynı mantık)
function sbFiltreliSorular() {
  const dersKey = sbDersState.secilenDers;
  const dersSorular = SORULAR.filter(s => s.ders === dersKey);
  return dersSorular.filter(s => {
    const seviyeOk = (s.seviye || 'baslangic') === sbState.seviye;
    const konuOk = sbState.secilenKonu === 'Tümü' || s.konu === sbState.secilenKonu;
    return seviyeOk && konuOk;
  });
}
