let sbNav = { sinav: null };

function sbVgDersByKey(key) {
  for (const grup of ['TYT', 'AYT', 'YDT']) {
    const f = (VG_DERSLER[grup] || []).find(d => d.key === key);
    if (f) return Object.assign({ grupAd: grup }, f);
  }
  return null;
}

function sbSecSinav(s) { sbNav.sinav = s; renderSoruBankasi(document.getElementById('mainContent')); }
function sbGeriSinav() { sbNav.sinav = null; sbDersState.secilenDers = null; renderSoruBankasi(document.getElementById('mainContent')); }

function renderSoruBankasi(el) {
  // 1) Sınav türü seçimi
  if (!sbDersState.secilenDers && !sbNav.sinav) {
    el.innerHTML = `
    <div class="fade-up sb-bg">
      <div style="padding:20px 0 8px;position:relative;text-align:center;">
        <button onclick="switchToTab('dashboard')" style="position:absolute;left:0;top:16px;background:none;border:none;cursor:pointer;padding:0;"><img src="${GERI_TUS_ICON}" style="width:48px;height:48px;"></button>
        <div style="font-family:'Playfair Display',serif;font-size:1.85rem;font-weight:900;letter-spacing:3px;margin-top:14px;color:var(--accent);text-shadow:0 1px 0 rgba(255,255,255,0.5),0 2px 3px rgba(120,80,20,0.25);">
          <span style="opacity:0.55;font-size:1.1rem;vertical-align:middle;">✦</span>
          &nbsp;SORU BANKAM&nbsp;
          <span style="opacity:0.55;font-size:1.1rem;vertical-align:middle;">✦</span>
        </div>
        <div style="width:120px;height:2px;margin:8px auto 0;background:linear-gradient(90deg,transparent,var(--accent),transparent);"></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px;max-width:280px;margin-left:auto;margin-right:auto;">
        <img onclick="sbSecSinav('TYT')" src='${SB_SINAV_BANNER.TYT}' style="width:100%;height:auto;display:block;border-radius:12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.3);">
        <img onclick="sbSecSinav('AYT')" src='${SB_SINAV_BANNER.AYT}' style="width:100%;height:auto;display:block;border-radius:12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.3);">
      </div>
      <div style="width:calc(50% - 7px);max-width:133px;margin:14px auto 0;">
        <img onclick="sbSecSinav('YDT')" src='${SB_SINAV_BANNER.YDT}' style="width:100%;height:auto;display:block;border-radius:12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.3);">
      </div>
    </div>`;
    return;
  }

  // 2) Ders seçimi
  if (!sbDersState.secilenDers) {
    el.innerHTML = `
    <div class="fade-up sb-bg">
      <div style="padding:20px 0 8px;">
        <button class="btn-link" onclick="sbGeriSinav()" style="text-align:left;margin:0 0 6px;padding:0;display:flex;align-items:center;gap:6px;"><img src="${GERI_TUS_ICON}" style="width:44px;height:44px;">Sınav Türleri</button>
        <div style="font-family:'Playfair Display',serif;font-size:1.5rem;font-weight:900;">📝 ${sbNav.sinav} Soru Bankası</div>
        <div style="font-size:0.82rem;color:var(--text3);margin-top:4px;">Çalışmak istediğin dersi seç</div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:8px;">
        ${SB_TREE[sbNav.sinav].map(t => {
          const kayitli = SB_DERSLER.find(x => x.key === t[0]);
          const d = kayitli || { key: t[0], ad: sbNav.sinav + ' ' + t[1], logo: t[2], grad: 'linear-gradient(135deg,#475569,#64748b)' };
          const gorsel = SB_TYT_KART_GORSEL[t[0]];
          if (gorsel) {
            return `<img onclick="sbSecDers('${d.key}')" src='${gorsel}' style="width:100%;height:auto;display:block;border-radius:18px;cursor:pointer;box-shadow:0 4px 16px rgba(0,0,0,0.25);">`;
          }
          const dersSorular = SORULAR.filter(s => s.ders === d.key);
          const cozulen = dersSorular.filter(s => sbState.cevaplar[s.id]).length;
          const dogru = dersSorular.filter(s => sbState.cevaplar[s.id] === s.dogru).length;
          const pct = cozulen > 0 ? Math.round(dogru/cozulen*100) : null;
          return `
          <div onclick="sbSecDers('${d.key}')" style="
            background:${d.grad};
            border-radius:18px;padding:18px 10px 14px;
            cursor:pointer;position:relative;overflow:hidden;
            box-shadow:0 4px 16px rgba(0,0,0,0.25);">
            <div style="font-size:2.1rem;margin-bottom:16px;line-height:1;">${d.logo}</div>
            <div style="font-weight:800;font-size:0.85rem;color:#fff;line-height:1.25;">${sbNav.sinav} ${t[1]}</div>
            ${pct !== null ? `<div style="margin-top:14px;font-size:0.65rem;background:rgba(255,255,255,0.2);color:#fff;padding:3px 8px;border-radius:20px;display:inline-block;">%${pct} başarı</div>` : `<div style="margin-top:14px;font-size:0.65rem;background:rgba(255,255,255,0.15);color:rgba(255,255,255,0.85);padding:3px 8px;border-radius:20px;display:inline-block;">Başla →</div>`}
          </div>`;
        }).join('')}
      </div>
    </div>`;
    return;
  }

  // Seçili derse göre soruları filtrele
  const dersKey = sbDersState.secilenDers;
  const dersSorular = SORULAR.filter(s => s.ders === dersKey);
  const vgD = sbVgDersByKey(dersKey);
  const dersInfo = vgD
    ? { key: dersKey, ad: vgD.grupAd + ' ' + vgD.ad, logo: vgD.emoji, renk: vgD.renk, grad: vgD.grad }
    : (SB_DERSLER.find(d => d.key === dersKey) || SB_DERSLER[0]);
  // Konular müfredattan (Veri Girişi ile aynı listeler); yoksa sorulardan türet
  const konular = ['Tümü', ...(vgD ? vgD.kazanimlar : [...new Set(dersSorular.map(s => s.konu))])];
  const filtreler = ['Tümü', 'Doğru', 'Yanlış', 'Çözülmemiş'];

  let dogru = 0, yanlis = 0, cozulmemis = 0;
  dersSorular.forEach(s => {
    const cevap = sbState.cevaplar[s.id];
    if (!cevap) cozulmemis++;
    else if (cevap === s.dogru) dogru++;
    else yanlis++;
  });
  const toplam = dersSorular.length;
  const cozulen = dogru + yanlis;
  const pct = cozulen > 0 ? Math.round(dogru / cozulen * 100) : 0;

  // ── KONU SEÇİM EKRANI (kart tasarımı) ──
  if (sbState.secilenKonu === null) {
    const konularSade = konular.slice(1); // 'Tümü' hariç
    const konuKart = (baslik, konuKey, soruSayi, no) => `
      <div onclick="sbSecKonu('${(konuKey || '').replace(/'/g, "\\'")}')"
        style="background:#fff;border-radius:18px;padding:20px 14px;margin-bottom:12px;cursor:pointer;box-shadow:0 3px 12px rgba(0,0,0,0.18);display:flex;align-items:center;gap:12px;min-height:60px;">
        <span style="font-weight:800;font-size:0.9rem;flex:1;letter-spacing:0.3px;line-height:1.35;">${no ? no + '- ' : ''}${baslik.toLocaleUpperCase('tr-TR')}${konuOrtakEtiketHtml(dersKey, konuKey)}</span>
        <span style="display:flex;flex-direction:column;align-items:flex-end;gap:2px;">
          <span style="font-size:1.25rem;">📖</span>
          <span style="font-size:0.62rem;color:var(--text3);font-weight:700;">${soruSayi} soru</span>
        </span>
      </div>`;
    el.innerHTML = `
    <div class="fade-up sb-bg">
      <div style="padding-top:12px;"></div>
      <div style="background:${dersInfo.grad};border-radius:24px;padding:14px 12px 4px;box-shadow:0 6px 24px rgba(0,0,0,0.2);">
        <div style="background:#fff;border-radius:14px;padding:8px 10px;display:flex;align-items:center;gap:8px;margin-bottom:12px;">
          <button onclick="sbSecDers(null)" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:36px;height:36px;"></button>
          <div style="flex:1;text-align:center;font-weight:900;font-size:1rem;letter-spacing:1px;margin-right:36px;">${dersInfo.ad.toLocaleUpperCase('tr-TR')}</div>
        </div>
        ${konularSade.map((k, i) => konuKart(k, k, dersSorular.filter(s => s.konu === k).length, String(i + 1).padStart(2, '0'))).join('')}
      </div>
    </div>`;
    return;
  }

  // ── SEVİYE SEÇİM EKRANI (Kolay / Orta / Zor / Çıkmış) — modüler kart tasarımı ──
  if (sbState.seviye === null) {
    const konuAd = sbState.secilenKonu === 'Tümü' ? 'Tüm Sorular' : sbState.secilenKonu;
    const konuSorular = dersSorular.filter(s => sbState.secilenKonu === 'Tümü' || s.konu === sbState.secilenKonu);
    const cozulduSay = arr => arr.filter(s => sbState.cevaplar[s.id]).length;
    const konuToplam = konuSorular.length;
    const konuCozulen = cozulduSay(konuSorular);
    const dersToplam = dersSorular.length;
    const dersCozulen = cozulduSay(dersSorular);
    const svRenkler = { baslangic: '#22c55e', orta: '#eab308', zor: '#ef4444', osym: '#6366f1', cikmis: '#fb923c' };
    const svAdlar = { baslangic: 'Kolay', orta: 'Orta', zor: 'Zor', osym: 'ÖSYM Tarzı', cikmis: 'Çıkmış' };
    if (typeof sbState.seviyeGecici === 'undefined') sbState.seviyeGecici = null;

    const kart = (sv, tam) => {
      const arr = konuSorular.filter(s => (s.seviye || 'baslangic') === sv);
      const toplam = arr.length, cozulen = cozulduSay(arr);
      const secili = sbState.seviyeGecici === sv;
      const bitti = toplam > 0 && cozulen === toplam;
      return `
        <div onclick="sbSeviyeSec('${sv}')"
          style="${tam ? 'grid-column:1 / -1;' : ''}background:#fff;border-radius:16px;padding:16px 14px;cursor:pointer;position:relative;
                 border:2px solid ${secili ? 'var(--accent)' : '#e5e7eb'};
                 box-shadow:${secili ? '0 4px 16px rgba(245,200,66,0.35)' : '0 2px 8px rgba(0,0,0,0.06)'};">
          ${bitti ? '<span style="position:absolute;top:10px;right:10px;width:22px;height:22px;border-radius:50%;background:#22c55e;color:#fff;font-size:0.78rem;font-weight:900;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(34,197,94,0.45);">✓</span>' : ''}
          <div style="display:flex;align-items:center;gap:7px;margin-bottom:8px;">
            <span style="width:10px;height:10px;border-radius:50%;background:${svRenkler[sv]};display:inline-block;"></span>
            <span style="font-weight:800;font-size:1rem;color:#1f2937;">${svAdlar[sv]}</span>
          </div>
          <div style="display:flex;align-items:center;gap:5px;font-size:0.76rem;color:var(--text3);">
            <span>📋</span><span>${toplam === 0 && sv === 'osym' ? 'Çok yakında' : cozulen + '/' + toplam + ' Çözüldü'}</span>
          </div>
        </div>`;
    };

    el.innerHTML = `
    <div class="fade-up sb-bg" style="max-width:480px;margin:0 auto;">
      <div style="display:flex;align-items:center;gap:10px;padding:16px 0 4px;">
        <button onclick="sbState.secilenKonu=null;sbState.seviye=null;renderSoruBankasi(document.getElementById('mainContent'))" style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:6px 12px;font-size:0.82rem;color:var(--text2);cursor:pointer;display:flex;align-items:center;gap:6px;"><img src="${GERI_TUS_ICON}" style="width:44px;height:44px;">Konular</button>
      </div>

      <div style="background:#fff;border-radius:22px;padding:22px 20px;margin-top:10px;box-shadow:0 4px 20px rgba(0,0,0,0.08);">
        <div style="font-family:'Playfair Display',serif;font-size:1.6rem;font-weight:900;color:${dersInfo.renk};margin-bottom:8px;">${konuAd}</div>
        <div style="display:flex;align-items:center;gap:16px;margin-bottom:20px;flex-wrap:wrap;">
          <span style="display:flex;align-items:center;gap:5px;font-size:0.82rem;color:var(--text2);font-weight:600;">${dersInfo.logo} ${dersInfo.ad}</span>
          <span style="display:flex;align-items:center;gap:5px;font-size:0.82rem;color:var(--text2);font-weight:600;">📋 ${konuCozulen}/${konuToplam} Çözüldü</span>
        </div>

        <div style="font-weight:800;font-size:1.05rem;color:#1f2937;margin-bottom:4px;">Zorluk Seviyesi Seçin</div>
        <div style="font-size:0.78rem;color:var(--text3);margin-bottom:16px;line-height:1.4;">Seviyene en uygun zorlukta sorularla karşılaşmak için seçim yap</div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px;">
          ${kart('baslangic')}${kart('orta')}${kart('zor')}${kart('osym')}${(state.csAcik !== false) ? kart('cikmis', true) : ''}
        </div>

        <button onclick="${sbState.seviyeGecici ? `sbSecSeviye('${sbState.seviyeGecici}')` : `alert('Lütfen önce bir zorluk seviyesi seç.')`}"
          style="width:100%;padding:15px;border:none;border-radius:14px;font-weight:800;font-size:0.95rem;cursor:pointer;
                 background:${sbState.seviyeGecici ? 'linear-gradient(135deg,#4338ca,#6366f1)' : '#d1d5db'};
                 color:#fff;box-shadow:${sbState.seviyeGecici ? '0 4px 16px rgba(67,56,202,0.35)' : 'none'};">
          Teste Başla  →
        </button>
      </div>
    </div>`;
    return;
  }

  let goruntulenecek = dersSorular.filter(s => {
    const seviyeOk = (s.seviye || 'baslangic') === sbState.seviye;
    const konuOk = sbState.secilenKonu === 'Tümü' || s.konu === sbState.secilenKonu;
    const cevap = sbState.cevaplar[s.id];
    let filtreOk = true;
    if (sbState.filtre === 'Doğru') filtreOk = cevap === s.dogru;
    else if (sbState.filtre === 'Yanlış') filtreOk = cevap && cevap !== s.dogru;
    else if (sbState.filtre === 'Çözülmemiş') filtreOk = !cevap;
    return seviyeOk && konuOk && filtreOk;
  });

  // ── TEK TEK SORU GÖRÜNÜMÜ (sınav tarzı: logo üst bar, kalem/silgi, A-E cevap barı) ──
  if (typeof sbState.soruIdx !== 'number') sbState.soruIdx = 0;
  if (sbState.soruIdx >= goruntulenecek.length) sbState.soruIdx = Math.max(0, goruntulenecek.length - 1);

  const ustBar = `
    <div style="display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:12px 14px;background:#fff;border-bottom:1px solid var(--border);position:sticky;top:0;z-index:20;margin:0 -16px 0;">
      <div style="justify-self:start;">
        <button onclick="clearInterval(sbTimerState.int); sbState.seviye=null; renderSoruBankasi(document.getElementById('mainContent'))" style="background:var(--surface2);border:1px solid var(--border);color:var(--text2);border-radius:10px;padding:6px 12px 6px 6px;font-size:0.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;"><img src="${GERI_TUS_ICON}" style="width:28px;height:28px;">Geri</button>
      </div>
      <div style="display:flex;align-items:center;gap:6px;justify-self:center;">
        <span style="font-size:1.2rem;">🧭</span>
        <span style="font-family:'Playfair Display',serif;font-weight:900;font-size:0.98rem;color:var(--accent);white-space:nowrap;">YKS Pusulam</span>
      </div>
      <div style="justify-self:end;">
        <button onclick="sbTestiBitir()" style="background:var(--red);color:#fff;border:none;border-radius:10px;padding:8px 14px;font-size:0.8rem;font-weight:800;cursor:pointer;">Testi Bitir</button>
      </div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 2px 2px;">
      <span style="background:var(--accent);color:#fff;width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:0.95rem;">${sbState.soruIdx + 1}</span>
      <span id="sbTimerChip" style="background:#dbeafe;color:#1d4ed8;font-weight:800;font-size:0.9rem;padding:7px 16px;border-radius:20px;">${sbFmtTime(0)}</span>
      <span style="width:34px;"></span>
    </div>`;

  if (goruntulenecek.length === 0) {
    el.innerHTML = `<div class="fade-up sb-bg">${ustBar}
      <div class="empty-state"><div class="icon">📚</div><div>Bu bölüme henüz soru eklenmedi.</div></div></div>`;
    return;
  }

  const soru = goruntulenecek[sbState.soruIdx];
  const ilk = sbState.soruIdx === 0;
  const son = sbState.soruIdx === goruntulenecek.length - 1;
  const cevap = sbState.cevaplar[soru.id];
  sbQuestionStartTs = Date.now();
  const sbFlipClass = sbGecisYon === 'next' ? 'page-flip-next' : (sbGecisYon === 'prev' ? 'page-flip-prev' : '');
  sbGecisYon = null;
  el.innerHTML = `
  <div class="fade-up sb-bg">
    ${ustBar}
    <div style="position:relative;" id="sbCardWrap" class="${sbFlipClass}">
      ${renderSoruCard(soru, sbState.soruIdx + 1)}
      <canvas id="sbCanvas" style="position:absolute;inset:0;top:0;left:0;pointer-events:none;touch-action:pan-y;"></canvas>
    </div>

    <div style="display:flex;align-items:center;gap:8px;padding:14px 0 20px;">
      <div style="position:relative;">
        <button id="sbPenBtn" onclick="sbPenClick()" title="Kalem" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.1rem;cursor:pointer;">✏️</button>
        <div id="sbPenPanel" style="display:none;position:absolute;bottom:50px;left:0;background:#fff;border:1px solid var(--border);border-radius:12px;padding:8px;box-shadow:0 6px 20px rgba(0,0,0,0.18);gap:10px;align-items:center;z-index:30;">
          ${[2,4,7].map(sz => `<button onclick="sbPenSize(${sz})" style="background:var(--surface2);border:none;border-radius:50%;width:${18+sz*2}px;height:${18+sz*2}px;display:flex;align-items:center;justify-content:center;cursor:pointer;"><span style="background:#2563eb;border-radius:50%;width:${sz*2}px;height:${sz*2}px;display:inline-block;"></span></button>`).join('')}
        </div>
      </div>
      <button id="sbEraserBtn" onclick="sbEraserClick()" title="Silgi" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.1rem;cursor:pointer;">🧹</button>
      <button onclick="sbClearClick()" title="Hepsini Sil" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.1rem;cursor:pointer;">🗑️</button>

      <span style="width:1px;height:30px;background:var(--border);margin:0 4px;"></span>

      <button onclick="sbState.soruIdx=0; renderSoruBankasi(document.getElementById('mainContent')); window.scrollTo(0,0)" ${ilk ? 'disabled style="opacity:0.35;"' : ''} title="İlk Soru (En Başa)" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.2rem;cursor:pointer;color:var(--text2);">⏮</button>
      <button onclick="sbGitSoru(-1)" ${ilk ? 'disabled style="opacity:0.35;"' : ''} title="Önceki Soru" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.2rem;cursor:pointer;color:var(--text2);">‹</button>
      <button onclick="sbGitSoru(1)" ${son ? 'disabled style="opacity:0.35;"' : ''} title="Sonraki Soru" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.2rem;cursor:pointer;color:var(--text2);">›</button>
      <button onclick="sbState.soruIdx=${goruntulenecek.length - 1}; renderSoruBankasi(document.getElementById('mainContent')); window.scrollTo(0,0)" ${son ? 'disabled style="opacity:0.35;"' : ''} title="Son Soru (En Sona)" style="background:#fff;border:1px solid var(--border);border-radius:12px;width:44px;height:44px;font-size:1.2rem;cursor:pointer;color:var(--text2);">⏭</button>
    </div>
  </div>`;

  sbInitCanvas();
  sbTimerStart();
  attachSwipeNav('sbCardWrap',
    () => { if (sbState.soruIdx < goruntulenecek.length - 1) { sbGecisYon = 'next'; sbGitSoru(1); } },
    () => { if (sbState.soruIdx > 0) { sbGecisYon = 'prev'; sbGitSoru(-1); } },
    () => !!sbDraw.mode);
}

function sbAnaSayfa() {
  if (!confirm('Ana sayfaya dönmek istiyor musun? Testten çıkacaksın.')) return;
  clearInterval(sbTimerState.int);
  switchToTab('dashboard');
}

function sbTestiBitir() {
  sbSonucGoster(false);
}

function sbSonucGoster(otomatikMi) {
  sbSonSonucOtomatikMi = otomatikMi;
  clearInterval(sbTimerState.int);
  const filtreli = sbFiltreliSorular();
  const toplam = filtreli.length;
  let dogru = 0, yanlis = 0, bos = 0, toplamSure = 0, sureSayisi = 0;
  filtreli.forEach(s => {
    const c = sbState.cevaplar[s.id];
    if (!c) bos++;
    else if (c === s.dogru) dogru++;
    else yanlis++;
    if (sbState.sureler[s.id]) { toplamSure += sbState.sureler[s.id]; sureSayisi++; }
  });
  const net = dogru - yanlis / 4;
  const oran = toplam > 0 ? (net / toplam * 100) : 0;
  const oranGosterim = Math.round(oran * 10) / 10;
  const ortSureSn = sureSayisi > 0 ? Math.round(toplamSure / sureSayisi) : 0;
  const ortSureDk = ortSureSn > 0 ? (ortSureSn / 60).toFixed(1) : '—';

  let yorum, renk;
  if (oran <= 50)      { yorum = 'Başarı seviyeniz oldukça düşük, bu konuyu tekrar çalışmanız gerekiyor.'; renk = 'var(--red)'; }
  else if (oran <= 70)  { yorum = 'Başarı seviyeniz orta, başarı seviyenizi hatalı olduğunuz soruların çözümlerini öğrenerek arttırabilirsiniz.'; renk = '#f97316'; }
  else if (oran <= 85)  { yorum = 'Başarı seviyeniz iyi. Zor seviyedeki sorularla çalışma yaparsanız başarınız çok iyi olacaktır.'; renk = '#ca8a04'; }
  else if (oran <= 90)  { yorum = 'Başarınız çok yüksek, tebrikler!'; renk = 'var(--green)'; }
  else                 { yorum = 'Başarınız muhteşem!'; renk = '#16a34a'; }

  const stat = (label, val, col) => `
    <div style="background:var(--surface2);border-radius:14px;padding:14px 8px;text-align:center;">
      <div style="font-size:1.5rem;font-weight:900;color:${col || 'var(--text1)'};">${val}</div>
      <div style="font-size:0.7rem;color:var(--text3);font-weight:700;margin-top:2px;">${label}</div>
    </div>`;

  const el = document.getElementById('mainContent');
  el.innerHTML = `
  <div class="fade-up" style="max-width:480px;margin:0 auto;padding:20px 0;">
    <div style="background:#fff;border-radius:22px;padding:26px 22px;box-shadow:0 4px 20px rgba(0,0,0,0.08);text-align:center;">
      <div style="font-size:2.2rem;">${otomatikMi ? '🏁' : '⏹️'}</div>
      <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;margin:6px 0 2px;">${otomatikMi ? 'Test Tamamlandı!' : 'Test Sonlandırıldı'}</div>
      <div style="font-size:0.8rem;color:var(--text3);margin-bottom:20px;">${dersInfoAd(sbDersState.secilenDers)} · ${sbState.secilenKonu === 'Tümü' ? 'Tüm Konular' : sbState.secilenKonu}</div>

      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:18px;">
        ${stat('Toplam', toplam)}
        ${stat('Doğru', dogru, 'var(--green)')}
        ${stat('Yanlış', yanlis, 'var(--red)')}
        ${stat('Boş', bos, 'var(--text3)')}
      </div>

      <div style="background:${renk}14;border:2px solid ${renk};border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;color:var(--text3);font-weight:700;margin-bottom:2px;">BAŞARI ORANI (Net/Toplam)</div>
        <div style="font-size:2.1rem;font-weight:900;color:${renk};">%${oranGosterim}</div>
        <div style="font-size:0.85rem;font-weight:800;color:${renk};margin-top:2px;">${yorum}</div>
      </div>

      <div style="display:flex;align-items:center;justify-content:center;gap:8px;font-size:0.85rem;color:var(--text2);font-weight:600;margin-bottom:22px;">
        ⏱️ Ortalama soru çözme süresi: <strong>${ortSureDk} dk</strong>
      </div>

      <button onclick="sbCevaplariIncele()"
        style="width:100%;padding:14px;border:none;border-radius:14px;font-weight:800;font-size:0.9rem;cursor:pointer;background:var(--accent);color:#fff;margin-bottom:10px;">
        📋 Cevapları Kontrol Et
      </button>

      <button onclick="sbState.seviye=null;sbState.seviyeGecici=null;sbState.soruIdx=0;renderSoruBankasi(document.getElementById('mainContent'));window.scrollTo(0,0)"
        style="width:100%;padding:14px;border:none;border-radius:14px;font-weight:800;font-size:0.9rem;cursor:pointer;background:linear-gradient(135deg,#4338ca,#6366f1);color:#fff;margin-bottom:10px;">
        ↩ Seviye Seçimine Dön
      </button>
    </div>
  </div>`;
}

// ── Cevapları Kontrol Et: doğru/yanlış/boş listesi + her soru için "Cevabı Gör" ──
function sbCevaplariIncele() {
  sbState.incelemeModu = true;
  renderSbInceleme();
}

function renderSbInceleme() {
  const filtreli = sbFiltreliSorular();
  const el = document.getElementById('mainContent');

  const satirlar = filtreli.map((s, i) => {
    const cevap = sbState.cevaplar[s.id];
    const acik = !!sbState.incelemeAcik[s.id];
    let durumEtiket, durumRenk;
    if (!cevap) { durumEtiket = '➖ Boş'; durumRenk = 'var(--text3)'; }
    else if (cevap === s.dogru) { durumEtiket = '✅ Doğru'; durumRenk = 'var(--green)'; }
    else { durumEtiket = '❌ Yanlış'; durumRenk = 'var(--red)'; }

    const detayHtml = acik ? `
      <div style="padding:0 14px 14px;">
        <div class="soru-metin" style="margin-bottom:10px;">${s.metin.replace ? s.metin.split('\n').join('<br>') : s.metin}</div>
        <div class="siklar">
          ${s.siklar.map(sik => {
            let sikClass = 'sik';
            if (sik.harf === s.dogru) sikClass += ' correct-sik';
            else if (sik.harf === cevap) sikClass += ' wrong-sik';
            return `<button class="${sikClass}" disabled><span class="sik-harf">${sik.harf}</span><span>${sik.metin}</span></button>`;
          }).join('')}
        </div>
        <div class="aciklama-box show" style="margin-top:10px;">📖 <strong>Açıklama:</strong> ${s.aciklama}</div>
      </div>` : '';

    return `
      <div style="background:#fff;border:1px solid var(--border);border-radius:14px;margin-bottom:10px;overflow:hidden;">
        <div style="display:flex;align-items:center;gap:10px;padding:12px 14px;">
          <span style="background:var(--surface2);color:var(--text2);width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:0.85rem;flex-shrink:0;">${i + 1}</span>
          <div style="flex:1;min-width:0;">
            <div style="font-size:0.8rem;font-weight:700;color:var(--text1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${s.konu}</div>
            <div style="font-size:0.78rem;font-weight:800;color:${durumRenk};margin-top:2px;">${durumEtiket}</div>
          </div>
          <button onclick="sbInceleToggle('${s.id}')" style="background:var(--accent);color:#fff;border:none;border-radius:10px;padding:8px 12px;font-size:0.78rem;font-weight:800;cursor:pointer;flex-shrink:0;">${acik ? '🙈 Gizle' : '👁️ Cevabı Gör'}</button>
        </div>
        ${detayHtml}
      </div>`;
  }).join('');

  el.innerHTML = `
  <div class="fade-up" style="max-width:520px;margin:0 auto;padding:16px 0;">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;">
      <button onclick="sbState.incelemeModu=false;sbSonucGosterYeniden()" style="background:var(--surface2);border:1px solid var(--border);color:var(--text2);border-radius:10px;padding:6px 12px 6px 6px;font-size:0.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;"><img src="${GERI_TUS_ICON}" style="width:28px;height:28px;">Geri</button>
      <div style="font-family:'Playfair Display',serif;font-size:1.15rem;font-weight:900;">📋 Cevapları Kontrol Et</div>
    </div>
    ${satirlar || '<div class="empty-state"><div class="icon">📚</div><div>Gösterilecek soru yok.</div></div>'}
  </div>`;
}

function sbInceleToggle(soruId) {
  sbState.incelemeAcik[soruId] = !sbState.incelemeAcik[soruId];
  renderSbInceleme();
}

// Sonuç ekranına, otomatik/manuel ayrımını tekrar hesaplamadan geri dönmek için
let sbSonSonucOtomatikMi = false;
function sbSonucGosterYeniden() {
  sbSonucGoster(sbSonSonucOtomatikMi);
}
function dersInfoAd(key) {
  const d = sbVgDersByKey(key);
  return d ? d.grupAd + ' ' + d.ad : (SB_DERSLER.find(x => x.key === key) || {}).ad || '';
}

function sbFmtTime(s) {
  const m = Math.floor(s / 60), ss = s % 60;
  return String(m).padStart(2, '0') + ':' + String(ss).padStart(2, '0');
}
function sbTimerStart() {
  clearInterval(sbTimerState.int);
  sbTimerState.sec = 0;
  const chip = document.getElementById('sbTimerChip');
  if (chip) chip.textContent = sbFmtTime(sbTimerState.sec);
  sbTimerState.int = setInterval(() => {
    sbTimerState.sec = sbTimerState.sec + 1;
    const c = document.getElementById('sbTimerChip');
    if (c) c.textContent = sbFmtTime(sbTimerState.sec);
  }, 1000);
}

// ── İşaretleme kalemi (canvas tabanlı, soru üzerine çizim) ──
function sbInitCanvas() {
  const canvas = document.getElementById('sbCanvas');
  const wrap = document.getElementById('sbCardWrap');
  if (!canvas || !wrap) return;
  const resize = () => { canvas.width = wrap.offsetWidth; canvas.height = wrap.offsetHeight; };
  resize();
  const ctx = canvas.getContext('2d');
  let drawing = false, last = null;
  const pos = e => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  canvas.onpointerdown = e => {
    if (!sbDraw.mode) return;
    drawing = true; last = pos(e);
    canvas.setPointerCapture(e.pointerId);
  };
  canvas.onpointermove = e => {
    if (!drawing || !sbDraw.mode) return;
    const p = pos(e);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    if (sbDraw.mode === 'pen') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = 'rgba(37,99,235,0.55)';
      ctx.lineWidth = sbDraw.size;
    } else {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.lineWidth = sbDraw.size * 4;
    }
    ctx.beginPath(); ctx.moveTo(last.x, last.y); ctx.lineTo(p.x, p.y); ctx.stroke();
    last = p;
  };
  const stop = () => { drawing = false; };
  canvas.onpointerup = stop;
  canvas.onpointercancel = stop;
  sbSyncCanvasMode();
}
function sbSyncCanvasMode() {
  const c = document.getElementById('sbCanvas');
  if (!c) return;
  c.style.pointerEvents = sbDraw.mode ? 'auto' : 'none';
  c.style.touchAction = sbDraw.mode ? 'none' : 'pan-y';
}
function sbUpdateToolUI() {
  const pen = document.getElementById('sbPenBtn');
  const er = document.getElementById('sbEraserBtn');
  if (pen) pen.style.background = sbDraw.mode === 'pen' ? '#dbeafe' : '#fff';
  if (er) er.style.background = sbDraw.mode === 'eraser' ? '#fee2e2' : '#fff';
}
function sbPenClick() {
  sbDraw.mode = sbDraw.mode === 'pen' ? null : 'pen';
  const panel = document.getElementById('sbPenPanel');
  if (panel) panel.style.display = (sbDraw.mode === 'pen') ? 'flex' : 'none';
  sbUpdateToolUI();
  sbSyncCanvasMode();
}
function sbPenSize(sz) {
  sbDraw.size = sz; sbDraw.mode = 'pen';
  const panel = document.getElementById('sbPenPanel');
  if (panel) panel.style.display = 'none';
  sbUpdateToolUI();
  sbSyncCanvasMode();
}
function sbEraserClick() {
  sbDraw.mode = sbDraw.mode === 'eraser' ? null : 'eraser';
  const panel = document.getElementById('sbPenPanel');
  if (panel) panel.style.display = 'none';
  sbUpdateToolUI();
  sbSyncCanvasMode();
}
function sbClearClick() {
  const c = document.getElementById('sbCanvas');
  if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
}

// Genel amaçlı parmakla sağa/sola kaydırma algılama: sola kaydır -> onNext, sağa kaydır -> onPrev
// Gerçek dokunma (touch) olayları kullanılır — telefonlarda pointer olaylarından daha güvenilirdir.
function attachSwipeNav(elId, onNext, onPrev, isBlocked) {
  const el = document.getElementById(elId);
  if (!el) return;
  let startX = 0, startY = 0, tracking = false;
  const esik = 50;
  el.addEventListener('touchstart', e => {
    if (isBlocked && isBlocked()) { tracking = false; return; }
    if (!e.touches || !e.touches.length) return;
    tracking = true;
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
  }, { passive: true });
  el.addEventListener('touchend', e => {
    if (!tracking) return;
    tracking = false;
    const t = e.changedTouches && e.changedTouches[0];
    if (!t) return;
    const dx = t.clientX - startX, dy = t.clientY - startY;
    if (Math.abs(dx) > esik && Math.abs(dx) > Math.abs(dy) * 1.3) {
      if (dx < 0) onNext(); else onPrev();
    }
  }, { passive: true });
  el.addEventListener('touchcancel', () => { tracking = false; }, { passive: true });
}

function sbGitSoru(dir) {
  sbState.soruIdx = Math.max(0, (sbState.soruIdx || 0) + dir);
  renderSoruBankasi(document.getElementById('mainContent'));
  window.scrollTo(0, 0);
}



function renderSoruCard(soru, siraNo) {
  const cevap = sbState.cevaplar[soru.id];
  const cevapVerildi = !!cevap;
  let cardClass = 'soru-card';
  if (cevapVerildi) cardClass += ' answered';

  const siklarHtml = soru.siklar.map(sik => {
    let sikClass = 'sik';
    if (cevap === sik.harf) sikClass += ' selected';
    return `
      <button class="${sikClass}" onclick="sbCevapla('${soru.id}','${sik.harf}')">
        <span class="sik-harf">${sik.harf}</span>
        <span>${sik.metin}</span>
      </button>`;
  }).join('');

  return `
  <div class="${cardClass}" id="sorucard-${soru.id}">
    <div class="soru-meta">
      <span class="soru-num">#${siraNo}</span>
      <span class="soru-konu-tag">${soru.konu}</span>
      ${soru.kaynak && soru.seviye === 'cikmis' ? `<span style="font-size:0.72rem;font-weight:800;color:#7c3aed;background:#f3e8ff;padding:3px 10px;border-radius:8px;">${soru.kaynak}</span>` : ''}
      <button id="kavanozbtn-${soru.id}" class="kavanoz-btn${kavanozdaMi(soru.id)?' active':''}" onclick="kavanozSoruToggle('${soru.id}')" title="Soru Kavanozu'na ekle" style="margin-left:auto;">
        <img src="${PUSULA_ICONS.soruKavanozuMini}" alt="Kavanoz">
      </button>
    </div>
    <div class="soru-metin">${soru.metin.replace ? soru.metin.split('\n').join('<br>') : soru.metin}</div>
    <div class="siklar">${siklarHtml}</div>
  </div>`;
}

function sbRenderAERow(soru, cevap) {
  return soru.siklar.map(sik => {
    let bg = '#fff', bd = '#e5e7eb', col = '#1f2937';
    if (cevap === sik.harf) { bg = 'var(--accent)'; bd = 'var(--accent)'; col = '#fff'; }
    return `<button onclick="sbCevapla('${soru.id}','${sik.harf}')" ${cevap ? 'disabled' : ''}
      style="width:46px;height:46px;border-radius:50%;border:2px solid ${bd};background:${bg};color:${col};font-weight:800;font-size:1rem;cursor:${cevap ? 'default' : 'pointer'};">${sik.harf}</button>`;
  }).join('');
}

function sbCevapla(soruId, sik) {
  if (sbState.cevaplar[soruId] === sik) return; // aynı şıkka tekrar basıldıysa gereksiz yeniden çizim yapma
  sbState.cevaplar[soruId] = sik;
  if (!sbState.cevapTs) sbState.cevapTs = {};
  sbState.cevapTs[soruId] = Date.now();
  sbState.sureler[soruId] = Math.max(1, Math.round((Date.now() - sbQuestionStartTs) / 1000));
  saveState(); // cevap kalıcı olsun (state.sb ile aynı referans) ve öğretmen/veli görünümünde doğru yansısın
  const soru = SORULAR.find(s => s.id === soruId);

  // Kartı ve A-E barını yeniden çiz (canvas çizimi ve kronometre korunur)
  const wrap = document.getElementById('sbCardWrap');
  if (wrap) {
    const canvas = document.getElementById('sbCanvas');
    const snapshot = canvas ? canvas.toDataURL() : null;
    wrap.innerHTML = renderSoruCard(soru, sbState.soruIdx + 1) + '<canvas id="sbCanvas" style="position:absolute;inset:0;top:0;left:0;pointer-events:none;touch-action:pan-y;"></canvas>';
    sbInitCanvas();
    if (snapshot) {
      const img = new Image();
      img.onload = () => {
        const c = document.getElementById('sbCanvas');
        if (c) c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      };
      img.src = snapshot;
    }
  }
  // A-E cevap barı kaldırıldı; şıklar doğrudan kart içinde işaretleniyor

  // Bu bölümdeki bütün sorular cevaplandıysa testi otomatik bitir
  const filtreli = sbFiltreliSorular();
  if (filtreli.length > 0 && filtreli.every(s => sbState.cevaplar[s.id])) {
    setTimeout(() => sbSonucGoster(true), 900);
  }
}

function sbSecDers(ders) {
  sbDersState.secilenDers = ders;
  sbState.secilenKonu = ders ? null : 'Tümü'; // önce konu seçim ekranı
  sbState.seviye = null;
  sbState.filtre = 'Tümü';
  renderSoruBankasi(document.getElementById('mainContent'));
  injectBackButton();
}

function sbSeviyeSec(sv) {
  if (sv === 'cikmis' && state.csAcik === false) return; // ÇS kapalıyken seçilemez
  sbState.seviyeGecici = sv;
  renderSoruBankasi(document.getElementById('mainContent'));
}

function sbSecSeviye(sv) {
  if (sv === 'cikmis' && state.csAcik === false) return; // ÇS kapalıyken erişilemez
  sbState.seviye = sv;
  if (sv === 'osym' && sbFiltreliSorular().length === 0) {
    sbState.seviye = null;
    alert('ÖSYM Tarzı sorular bu konuda çok yakında eklenecek.');
    return;
  }
  sbState.seviyeGecici = null;
  sbState.soruIdx = 0;
  renderSoruBankasi(document.getElementById('mainContent'));
  window.scrollTo(0, 0);
}

function sbSecKonu(konu) {
  sbState.secilenKonu = konu;
  sbState.seviye = null; // önce seviye seçim ekranı
  sbState.seviyeGecici = null;
  sbState.soruIdx = 0;
  renderSoruBankasi(document.getElementById('mainContent'));
  injectBackButton();
}

function sbSecKonuBtn(btn) {
  sbState.secilenKonu = btn.getAttribute('data-konu');
  renderSoruBankasi(document.getElementById('mainContent'));
  injectBackButton();
}

function sbSecFiltre(filtre) {
  sbState.filtre = filtre;
  renderSoruBankasi(document.getElementById('mainContent'));
  injectBackButton();
}

function sbSifirla() {
  if (confirm('Tüm cevaplar silinecek. Emin misin?')) {
    sbState.cevaplar = {};
    saveState();
    renderSoruBankasi(document.getElementById('mainContent'));
  }
}


