function baHesaplaDersBazliDetay() {
  const dersAnahtarlari = baSorumluDersAnahtarlari();
  const sonuc = [];
  dersAnahtarlari.forEach(giris => {
    const [sinav, dersKey] = giris.split('|');
    const dersObj = (VG_DERSLER[sinav] || []).find(d => d.key === dersKey);
    if (!dersObj) return;
    let toplam = 0, tamam = 0;
    dersObj.kazanimlar.forEach((_, ki) => {
      toplam++;
      try { if (vgGetItem('vgkbitti_' + dersKey + '_' + ki) === '1') tamam++; } catch(e){}
    });
    if (toplam > 0) {
      sonuc.push({ ad: dersObj.ad, sinav, pct: Math.round(tamam / toplam * 100), toplam, tamam });
    }
  });
  return sonuc;
}

// NOT: "Toplam Soru Sayısı", kullanıcının istediği gibi SADECE iki kaynağın toplamıdır:
// (1) Veri Girişi'nde (Derslerim > konu/test girişleri) çözülen soru sayısı, ve
// (2) Soru Bankası'nda cevaplanan soru sayısı. Denemeler (TYT/AYT tam deneme sonuçları) BURAYA
// kasıtlı olarak DAHİL EDİLMEZ — onlar zaten kendi "Denemelerim" ekranında ayrı gösteriliyor.
// Ayrıca Veri Girişi anahtarları artık öğrenciye özel state.vg içinde tutulduğu için (bkz.
// baVgTumAnahtarlar), eskisi gibi sadece ham localStorage taranarak BULUNAMIYORLARDI; bu yüzden
// toplam soru sayısı eksik/yanlış çıkıyordu. Artık state.vg + ham localStorage (eski kayıtlar
// için) birlikte taranıyor.
function baHesaplaSoruDurum() {
  let dogru = 0, yanlis = 0, bos = 0;
  try {
    baVgTumAnahtarlar().forEach(key => {
      try {
        const s = JSON.parse(vgGetItem(key) || '{}');
        dogru += (+s.d || 0); yanlis += (+s.y || 0); bos += (+s.b || 0);
      } catch(e){}
    });
  } catch(e){}
  try {
    Object.keys(sbState.cevaplar || {}).forEach(soruId => {
      const soru = SORULAR.find(s => s.id === soruId);
      if (!soru) return;
      if (sbState.cevaplar[soruId] === soru.dogru) dogru++; else yanlis++;
    });
  } catch(e){}
  return { toplam: dogru + yanlis + bos, dogru, yanlis, bos };
}

// NOT: Bu hesaplama, "Derslerim" (baRenderDersler) ekranındaki kazanım bazlı başarı
// yüzdesiyle BİREBİR AYNI formülü kullanır (net = doğru - yanlış/4; yüzde = net / TÜM
// çözülen soru [doğru+yanlış+BOŞ dahil]). Eskiden burada sadece doğru/(doğru+yanlış)
// hesaplanıyordu; bu, boş bırakılan soruları hesaba hiç katmadığı için (ör. 18 doğru,
// 0 yanlış, 3 boş) yanlışlıkla %100 gösteriyordu. İki ekran arasında da tutarlılık
// sağlanması için tek bir yerde (burada) hesaplanıp iki formülün asla birbirinden
// sapmaması hedeflenir.
function baZayifKonular(limit) {
  limit = limit || 3;
  const dersAnahtarlari = baSorumluDersAnahtarlari();
  const konular = [];
  dersAnahtarlari.forEach(giris => {
    const [sinav, dersKey] = giris.split('|');
    const dersObj = (VG_DERSLER[sinav] || []).find(d => d.key === dersKey);
    if (!dersObj) return;
    dersObj.kazanimlar.forEach((konuAd, ki) => {
      let d = 0, y = 0, b = 0;
      for (let t = 1; t <= vgKonuTestSayisi(dersKey, ki); t++) {
        try {
          const s = JSON.parse(vgGetItem('vgkz_' + dersKey + '_' + ki + '_' + t) || '{}');
          d += (+s.d || 0); y += (+s.y || 0); b += (+s.b || 0);
        } catch(e){}
      }
      const toplamSoru = d + y + b;
      if (toplamSoru >= 5) {
        const net = d - y / 4;
        const pct = Math.round((net / toplamSoru) * 100);
        konular.push({ dersAd: dersObj.ad, konuAd, dersKey, ki, sinav, pct, cozulen: toplamSoru });
      }
    });
  });
  konular.sort((a, b) => a.pct - b.pct);
  return konular.slice(0, limit);
}

function baHaftalikVeri() {
  const gunlukVeri = baGunlukVeri();
  const harita = {};
  gunlukVeri.forEach(v => { harita[v.tarih] = v.sayi; });
  const gunAdlari = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const sonuc = [];
  const bugun = new Date();
  for (let i = 6; i >= 0; i--) {
    const d = new Date(bugun);
    d.setDate(d.getDate() - i);
    const key = d.toISOString().slice(0, 10);
    sonuc.push({ tarih: key, gun: gunAdlari[d.getDay()], sayi: harita[key] || 0 });
  }
  return sonuc;
}

function baZayifKonuyaGit(sinav, dersKey, ki) {
  vgSetMenu('dersler');
  vgState.sinav = sinav;
  vgSetDers(dersKey);
  switchToTab('veriGirisi');
}

function baSureFmt(ms) {
  const dk = Math.round(ms / 60000);
  const s = Math.floor(dk / 60), d = dk % 60;
  if (s === 0) return d + ' dk';
  return s + ' sa' + (d > 0 ? ' ' + d + ' dk' : '');
}

function baHesaplaCalismaRitmi() {
  const sayac = state.sayac || {};
  const gunToplam = (gunKey) => {
    const gun = sayac[gunKey] || {};
    return Object.values(gun).reduce((a, v) => a + (+v || 0), 0);
  };
  const bugun = new Date();
  const bugunMs = gunToplam(bugunKey());
  let haftaToplam = 0;
  for (let i = 0; i < 7; i++) {
    const d = new Date(bugun);
    d.setDate(d.getDate() - i);
    haftaToplam += gunToplam(d.toISOString().slice(0, 10));
  }
  const haftalikOrtalamaMs = haftaToplam / 7;
  const son = state.sayacSon || null;
  return { bugunMs, haftalikOrtalamaMs, son, veriVar: Object.keys(sayac).length > 0 };
}

// Deneme (Veri Girişi > Denemeler) ders anahtarlarını BA_KATSAYI alan adlarına eşler
const BA_DENEME_KEY_MAP = {
  tytTurkce: 'tytTurkce', tytMatematik: 'tytMat', tytSosyal: 'tytSosyal', tytFen: 'tytFen',
  aytMatematik: 'aytMat', aytFizik: 'aytFizik', aytKimya: 'aytKimya', aytBiyoloji: 'aytBiyoloji',
  aytEdebiyat: 'aytEdebiyat', aytTarih1: 'aytTarih1', aytCografya1: 'aytCografya1',
  aytTarih2: 'aytTarih2', aytCografya2: 'aytCografya2', aytFelsefe: 'aytFelsefeGrubu', aytDin: 'aytDkab'
};
function baDenemeDersleriTumu() {
  return [
    ...DENEME_VG_DERSLER.TYT.map(d => Object.assign({}, d, { sinav: 'TYT' })),
    ...DENEME_VG_DERSLER.AYT.map(d => Object.assign({}, d, { sinav: 'AYT' })),
  ];
}
// Veri Girişi > Denemeler (vgd_) ve Denemelerim (vgud_) içinde dolu olan deneme slotlarını, en son
// güncellenene göre sıralar. Her kayıt { onek, no } döner — iki kaynak birbirine karışmaz.
function baSonDenemeNolar(adet) {
  const ALL = baDenemeDersleriTumu();
  const kaynaklar = [{ onek: 'vgd_', adet: 30 }, { onek: 'vgud_', adet: DENEME_TOPLAM }];
  const denemeler = [];
  kaynaklar.forEach(kn => {
    for (let no = 1; no <= kn.adet; no++) {
      let maxTs = 0, varMi = false;
      ALL.forEach(d => {
        try {
          const s = JSON.parse(vgGetItem(kn.onek + d.sinav + '_' + no + '_' + d.key) || '{}');
          if (s.d || s.y || s.b) { varMi = true; if (s.ts && s.ts > maxTs) maxTs = s.ts; }
        } catch(e){}
      });
      if (varMi) denemeler.push({ onek: kn.onek, no, ts: maxTs });
    }
  });
  denemeler.sort((a, b) => b.ts - a.ts);
  return denemeler.slice(0, adet).map(x => ({ onek: x.onek, no: x.no }));
}
// Bir deneme numarasının net'lerini BA_KATSAYI alan adlarıyla döner (onek: 'vgd_' Veri Girişi, 'vgud_' Denemelerim)
function baDenemeNetleriOku(no, onek) {
  onek = onek || 'vgd_';
  const n = {};
  baDenemeDersleriTumu().forEach(d => {
    try {
      const s = JSON.parse(vgGetItem(onek + d.sinav + '_' + no + '_' + d.key) || '{}');
      const dd = +s.d || 0, yy = +s.y || 0;
      if (s.d || s.y) {
        const mapKey = BA_DENEME_KEY_MAP[d.key];
        if (mapKey) n[mapKey] = Math.max(0, dd - yy / 4);
      }
    } catch(e){}
  });
  return n;
}
// Bir net setinden (OBP hariç) ham puanı hesaplar
function baHamPuanHesaplaTur(tur, n) {
  const kat = BA_KATSAYI[tur];
  let hamToplam = kat.taban, girisSayisi = 0;
  Object.keys(kat).filter(k => k !== 'taban' && k !== 'eksikTaban').forEach(key => {
    const v = parseFloat(n[key]);
    if (!isNaN(v) && n[key] !== '' && n[key] !== undefined) { hamToplam += v * kat[key]; girisSayisi++; }
  });
  return { hamToplam, girisSayisi };
}
// Son 3 denemenin (Veri Girişi > Denemeler) ortalamasından mevcut tahmini puanı hesaplar
function baMevcutPuanSonDenemelerden() {
  const sonNolar = baSonDenemeNolar(3);
  if (!sonNolar.length) return null;
  const { turler } = kbHedefPuanHesapla();
  if (!turler.length) return null;
  const obpKatkisi = baKendiObpKatkisi() || 0;
  const sonuc = {};
  turler.forEach(t => {
    let toplamHam = 0, sayac = 0;
    sonNolar.forEach(x => {
      const r = baHamPuanHesaplaTur(t.tur, baDenemeNetleriOku(x.no, x.onek));
      if (r.girisSayisi > 0) { toplamHam += r.hamToplam; sayac++; }
    });
    if (sayac > 0) sonuc[t.tur] = (toplamHam / sayac) + obpKatkisi;
  });
  return { sonuc, denemeSayisi: sonNolar.length };
}

function baHesaplaMevcutPuanKarti() {
  const k = state.kisisel || {};
  const { turler } = kbHedefPuanHesapla();
  if (!turler.length) return null;
  const mevcutVeri = baMevcutPuanSonDenemelerden();
  return {
    uni: k.uni || '',
    bolum: k.bolum || '',
    denemeSayisi: mevcutVeri ? mevcutVeri.denemeSayisi : 0,
    turler: turler.map(t => ({
      ad: t.ad,
      mevcut: (mevcutVeri && mevcutVeri.sonuc[t.tur] !== undefined) ? mevcutVeri.sonuc[t.tur] : null
    })),
    mevcutGirilmis: !!(mevcutVeri && mevcutVeri.denemeSayisi > 0)
  };
}

function baRenderGenelDurumum(el) {
  const { toplam: sorumluKonu, tamamlanan: tamamlananKonu } = baHesaplaSorumluKonular();
  const konuPct = sorumluKonu > 0 ? Math.round(tamamlananKonu / sorumluKonu * 100) : 0;
  const soruDurum = baHesaplaSoruDurum();
  const gunlukVeri = baGunlukVeri();
  const haftalikVeri = baHaftalikVeri();
  const zayifKonular = baZayifKonular(5);
  const calismaRitmi = baHesaplaCalismaRitmi();

  let gunlukOrtalama = null;
  const baslangic = state.kisisel && state.kisisel.baslangicTarih;
  if (baslangic) {
    const bas = new Date(baslangic);
    const bugun = new Date();
    const gunSayisi = Math.max(1, Math.round((bugun - bas) / 86400000) + 1);
    gunlukOrtalama = (soruDurum.toplam / gunSayisi).toFixed(1);
  }

  const r = 46, cx = 60, cy = 60, circ = 2 * Math.PI * r;
  const dash = sorumluKonu > 0 ? (konuPct / 100) * circ : 0;
  const donutSvg = `
    <svg width="120" height="120" viewBox="0 0 120 120">
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="rgba(150,110,40,0.18)" stroke-width="14"/>
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#d4af5a" stroke-width="14"
        stroke-dasharray="${dash} ${circ}" stroke-linecap="round"
        transform="rotate(-90 ${cx} ${cy})"/>
      <text x="${cx}" y="${cy+6}" text-anchor="middle" font-size="20" font-weight="900" fill="#3a2a15">%${konuPct}</text>
    </svg>`;

  const toplamSoruSayisi = soruDurum.toplam;

  const maxHafta = Math.max(...haftalikVeri.map(v => v.sayi), 1);
  const haftalikBarHtml = haftalikVeri.map(v => {
    const yukseklikPx = Math.round((v.sayi / maxHafta) * 90) + (v.sayi > 0 ? 8 : 2);
    return `
    <div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex:1;">
      <div style="font-size:0.68rem;font-weight:800;color:#3a2a15;">${v.sayi || ''}</div>
      <div style="width:70%;max-width:26px;height:${yukseklikPx}px;background:linear-gradient(180deg,#e9c66b,#a97e2f);border-radius:6px 6px 3px 3px;"></div>
      <div style="font-size:0.68rem;color:#8a7a5c;">${v.gun}</div>
    </div>`;
  }).join('');

  const zayifKonularHtml = zayifKonular.length ? zayifKonular.map((k, i) => `
    <div style="display:flex;align-items:center;justify-content:space-between;padding:8px 0;${i<zayifKonular.length-1?'border-bottom:1px solid rgba(150,110,40,0.15);':''}">
      <div style="font-size:0.82rem;color:#3a2a15;"><strong>${i+1}.</strong> ${k.konuAd} <span style="color:#b3452e;font-weight:800;">(%${k.pct})</span></div>
      <button onclick="baZayifKonuyaGit('${k.sinav}','${k.dersKey}',${k.ki})" style="background:none;border:none;color:#8a6a2f;font-size:0.75rem;font-weight:800;text-decoration:underline;cursor:pointer;white-space:nowrap;">Çalışmaya Başla</button>
    </div>`).join('') : '<div style="font-size:0.78rem;color:#8a7a5c;">Yeterli veri birikince zayıf konuların burada listelenecek (bir konuda en az 5 soru çözülmeli).</div>';

  let calismaRitmiHtml;
  if (!calismaRitmi.veriVar) {
    calismaRitmiHtml = '<div style="font-size:0.8rem;color:#8a7a5c;">Ders Sayacım\'ı kullanmaya başlayınca çalışma sürelerin burada görünecek.</div>';
  } else {
    const sonHtml = calismaRitmi.son
      ? (() => {
          const dk = Math.round((Date.now() - calismaRitmi.son.ts) / 60000);
          const zamanTxt = dk < 60 ? dk + ' dk önce' : (dk < 1440 ? Math.round(dk/60) + ' saat önce' : Math.round(dk/1440) + ' gün önce');
          return `${calismaRitmi.son.ders} · ${zamanTxt}`;
        })()
      : '—';
    calismaRitmiHtml = `
      <div style="display:flex;gap:18px;flex-wrap:wrap;">
        <div>
          <div style="font-size:0.68rem;color:#8a7a5c;">Bugün Çalışılan</div>
          <div style="font-size:1.15rem;font-weight:900;color:#3a2a15;">${baSureFmt(calismaRitmi.bugunMs)}</div>
        </div>
        <div>
          <div style="font-size:0.68rem;color:#8a7a5c;">Haftalık Ortalama</div>
          <div style="font-size:1.15rem;font-weight:900;color:#3a2a15;">${baSureFmt(calismaRitmi.haftalikOrtalamaMs)}</div>
        </div>
        <div>
          <div style="font-size:0.68rem;color:#8a7a5c;">Son Çalışma</div>
          <div style="font-size:0.9rem;font-weight:800;color:#3a2a15;">${sonHtml}</div>
        </div>
      </div>`;
  }

  el.innerHTML = `
  <div class="fade-up" style="max-width:640px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 50% 0%,rgba(233,198,107,0.35),transparent 60%),linear-gradient(160deg,#fdf6e3,#f3e6c4);border:1px solid rgba(150,110,40,0.35);box-shadow:0 10px 26px rgba(0,0,0,0.18);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">
        <button onclick="baSetView(null)" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <img src="${BA_ICON_GENEL}" style="width:34px;height:34px;border-radius:8px;">
        <div style="font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:900;color:#3a2a15;">Kapsamlı Başarı Analizi</div>
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:10px;">TAMAMLANAN KONU SAYISI</div>
        <div style="display:flex;align-items:center;gap:18px;">
          ${donutSvg}
          <div>
            <div style="font-weight:900;font-size:1.15rem;color:#3a2a15;">${tamamlananKonu} / ${sorumluKonu}</div>
            <div style="font-size:0.78rem;color:#8a7a5c;">konu tamamlandı</div>
            ${sorumluKonu === 0 ? '<div style="color:#b3452e;font-size:0.72rem;margin-top:4px;">Kişisel Bilgilerim\'de hazırlanacağın testleri seç</div>' : ''}
          </div>
        </div>
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:6px;">TOPLAM SORU SAYISI</div>
        <div style="font-size:1.9rem;font-weight:900;color:#3a2a15;">${toplamSoruSayisi.toLocaleString('tr-TR')}</div>
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:6px;">GÜNLÜK ORTALAMA ÇÖZÜLEN SORU SAYISI</div>
        ${gunlukOrtalama !== null
          ? `<div style="font-size:1.9rem;font-weight:900;color:#3a2a15;">${gunlukOrtalama}</div><div style="font-size:0.7rem;color:#8a7a5c;">Başlangıç tarihinden bugüne</div>`
          : `<div style="font-size:0.8rem;color:#8a7a5c;">Kişisel Bilgilerim'de "YksPusulam Başlangıç Tarihim"ni gir</div>`}
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:10px;">HAFTALIK ÇÖZÜLEN SORU</div>
        <div style="display:flex;align-items:flex-end;gap:6px;">${haftalikBarHtml}</div>
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:4px;">ZAYIF KONULAR</div>
        <div style="font-size:0.68rem;color:#8a7a5c;margin-bottom:8px;">Konu bazında en düşük doğru yüzdesine sahip 5 konu</div>
        ${zayifKonularHtml}
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-bottom:14px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:10px;">⏱️ ÇALIŞMA RİTMİ</div>
        ${calismaRitmiHtml}
      </div>

      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:10px;">GÜNLÜK ÇÖZÜLEN SORU GRAFİĞİ (TÜM ZAMANLAR)</div>
        ${baRenderGunlukGrafik(gunlukVeri)}
      </div>
    </div>
  </div>`;
}

let baZoom = 1;
function baRenderGunlukGrafik(veri) {
  if (!veri.length) {
    return `<div class="ba-empty">Henüz veri girişi yapılmadı. Dersler / Denemeler / Branş Denemeleri'nden soru girince burada görünecek.</div>`;
  }
  const genislikBirim = 36 * baZoom;
  const w = Math.max(280, veri.length * genislikBirim);
  const h = 140;
  const padTop = 16, padBottom = 24;
  const maxVal = Math.max(...veri.map(v => v.sayi), 1);
  const pts = veri.map((v, i) => {
    const x = (veri.length === 1) ? w/2 : (i / (veri.length - 1)) * (w - 20) + 10;
    const y = padTop + (1 - v.sayi / maxVal) * (h - padTop - padBottom);
    return { x, y, ...v };
  });
  const pathD = pts.map((p,i) => (i===0?'M':'L') + p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ');
  const noktalar = pts.map((p, i) => `
    <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="4" fill="var(--accent)" style="cursor:pointer;"
      onclick="baGosterGunDegeri('${p.tarih}', ${p.sayi})"></circle>`).join('');
  const tarihEtiketleri = pts.map(p => `
    <text x="${p.x.toFixed(1)}" y="${h-6}" font-size="9" fill="var(--text3)" text-anchor="middle">${p.tarih.slice(5)}</text>`).join('');

  return `
    <div class="ba-line-toolbar">
      <button class="ba-zoom-btn" onclick="baZoomChange(-1)">−</button>
      <button class="ba-zoom-btn" onclick="baZoomChange(1)">+</button>
    </div>
    <div class="ba-line-scroll">
      <svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
        <path d="${pathD}" fill="none" stroke="var(--accent)" stroke-width="2"/>
        ${noktalar}
        ${tarihEtiketleri}
      </svg>
    </div>
    <div class="ba-line-tooltip" id="baGunTooltip">Bir güne tıkla, o günkü soru sayısını gör</div>`;
}

function baZoomChange(delta) {
  baZoom = Math.max(0.5, Math.min(3, baZoom + delta * 0.25));
  renderGrafik();
}

function baGosterGunDegeri(tarih, sayi) {
  const el = document.getElementById('baGunTooltip');
  if (el) el.textContent = tarih + ' → ' + sayi + ' soru';
}

let baKonuGrafikState = null; // { dersKey, ki, dersAd, konuAd }
function baKonuGrafikAc(dersKey, ki, dersAd, konuAd) {
  baKonuGrafikState = { dersKey, ki, dersAd, konuAd };
  renderGrafik();
  injectBackButton();
}
function baKonuGrafikKapat() {
  baKonuGrafikState = null;
  renderGrafik();
  injectBackButton();
}
function baRenderKonuGrafikEkrani(el) {
  const { dersKey, ki, dersAd, konuAd } = baKonuGrafikState;
  const noktalar = [];
  for (let t = 1; t <= vgKonuTestSayisi(dersKey, ki); t++) {
    let s = {};
    try { s = JSON.parse(vgGetItem('vgkz_' + dersKey + '_' + ki + '_' + t) || '{}'); } catch(e){}
    const d = +s.d || 0, y = +s.y || 0, b = +s.b || 0;
    const toplam = d + y + b;
    if (toplam > 0) {
      const net = d - y / 4;
      const pct = Math.round((net / toplam) * 100);
      // Testin girildiği (son kaydedildiği) tarih: gg.aa — eski kayıtlarda ts yoksa tarih gösterilmez
      let tarih = '';
      if (s.ts) { const dt = new Date(s.ts); if (!isNaN(dt)) tarih = String(dt.getDate()).padStart(2,'0') + '.' + String(dt.getMonth()+1).padStart(2,'0'); }
      noktalar.push({ etiket: 'T' + t, deger: pct, tarih });
    }
  }
  el.innerHTML = `
  <div class="fade-up">
    <div style="display:flex;align-items:center;gap:10px;padding:16px 0 12px;">
      <button onclick="baKonuGrafikKapat()" style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:6px 12px 6px 6px;font-size:0.82rem;color:var(--text2);cursor:pointer;display:flex;align-items:center;"><img src="${GERI_TUS_ICON}" style="width:28px;height:28px;margin-right:4px;">Geri</button>
      <div>
        <div style="font-family:'Playfair Display',serif;font-size:1.1rem;font-weight:900;">📊 ${konuAd}</div>
        <div style="font-size:0.72rem;color:var(--text3);">${dersAd} · Testlerdeki başarı yüzdesi (%)</div>
      </div>
    </div>
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:12px;">
      ${baRenderComboChart(noktalar, 'konuGrafik', 'baComboTikGoster', 'Başarı %')}
    </div>
  </div>`;
}

function baRenderDersler(el) {
  // Seviye 1: sınav seçimi
  if (!baDersState.sinav) {
    el.innerHTML = `
    <div class="fade-up">
      ${baHeader(`<img src="${BA_ICON_DERSLER}" class="ba-icon-img">`, 'Derslerim', "baSetView(null)", 'linear-gradient(160deg,#2d6e56,#1f5442)')}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:4px;max-width:280px;margin-left:auto;margin-right:auto;">
        ${['TYT','AYT'].map(k => `
        <img onclick="baDersSetSinav('${k}')" src='${SB_SINAV_BANNER[k]}' style="width:100%;height:auto;display:block;border-radius:12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.3);">`).join('')}
      </div>
      <div style="width:calc(50% - 7px);max-width:133px;margin:14px auto 0;">
        <img onclick="baDersSetSinav('YDT')" src='${SB_SINAV_BANNER.YDT}' style="width:100%;height:auto;display:block;border-radius:12px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.3);">
      </div>
    </div>`;
    return;
  }

  const dersler = VG_DERSLER[baDersState.sinav] || [];

  // Seviye 2: ders seçimi
  if (!baDersState.ders) {
    el.innerHTML = `
    <div class="fade-up">
      ${baHeader(baDersState.sinav === 'TYT' ? '📘' : baDersState.sinav === 'AYT' ? '📗' : '🌍', baDersState.sinav + ' Derslerim', "baDersSetSinav(null)", 'linear-gradient(160deg,#2d6e56,#1f5442)')}
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;">
        ${dersler.map(d => {
          const gorsel = sbDersKartGorsel(d.key);
          if (gorsel) {
            return `<img onclick="baDersSetDers('${d.key}')" src='${gorsel}' style="width:100%;height:auto;display:block;border-radius:14px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.2);">`;
          }
          return `
        <div onclick="baDersSetDers('${d.key}')" style="background:${sbDersKartRenk(d.key)};border-radius:14px;padding:16px 10px 14px;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,0.2);">
          <div style="font-size:1.8rem;margin-bottom:8px;">${sbDersKartEmoji(d.key, d.emoji)}</div>
          <div style="font-weight:800;font-size:0.8rem;color:#fff;line-height:1.25;">${d.ad}</div>
        </div>`;
        }).join('')}
      </div>
    </div>`;
    return;
  }

  // Seviye 3: konu listesi — soru sayısı + başarı yüzdesi (net / toplam çözülen soru)
  const dersObj = dersler.find(d => d.key === baDersState.ders);
  if (!dersObj) { baDersSetDers(null); return; }

  if (baKonuGrafikState && baKonuGrafikState.dersKey === dersObj.key) { baRenderKonuGrafikEkrani(el); return; }

  const satirlar = dersObj.kazanimlar.map((k, ki) => {
    let toplamD = 0, toplamY = 0, toplamB = 0;
    for (let t = 1; t <= vgKonuTestSayisi(dersObj.key, ki); t++) {
      try {
        const s = JSON.parse(vgGetItem('vgkz_' + dersObj.key + '_' + ki + '_' + t) || '{}');
        toplamD += +s.d || 0; toplamY += +s.y || 0; toplamB += +s.b || 0;
      } catch(e){}
    }
    const toplamSoru = toplamD + toplamY + toplamB;
    const net = toplamD - toplamY / 4;
    const basariPct = toplamSoru > 0 ? Math.round((net / toplamSoru) * 100) : null;
    const renkPct = basariPct === null ? 'var(--text3)' : basariPct >= 75 ? 'var(--green)' : basariPct >= 50 ? 'var(--accent)' : 'var(--red)';

    const dersAdSafe = String(dersObj.ad).replace(/'/g, "\\'");
    const konuAdSafe = String(k).replace(/'/g, "\\'");
    return `
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px 14px;margin-bottom:8px;display:flex;align-items:center;gap:10px;">
        <span onclick="baKonuGrafikAc('${dersObj.key}',${ki},'${dersAdSafe}','${konuAdSafe}')" style="cursor:pointer;font-size:1rem;flex-shrink:0;" title="Başarı grafiği">📊</span>
        <span style="flex:1;font-size:0.85rem;font-weight:600;">${String(ki+1).padStart(2,'0')}. ${k}</span>
        <span style="font-size:0.72rem;color:var(--text3);text-align:right;">${toplamSoru} soru</span>
        <span style="font-size:0.82rem;font-weight:800;color:${renkPct};min-width:44px;text-align:right;">${basariPct === null ? '—' : '%' + basariPct}</span>
      </div>`;
  }).join('');

  el.innerHTML = `
  <div class="fade-up">
    ${baHeader(null, dersObj.ad, "baDersSetDers(null)")}
    ${satirlar}
  </div>`;
}

// Ders bazlı net kategorilerinin (Kişisel Bilgilerim'deki hedef netler ile aynı şema) hangi
// VG_DERSLER ders anahtarlarından oluştuğunu gösteren eşleme.
// BA_KATSAYI'deki her katsayı anahtarının, hangi VG_DERSLER (ince) ders anahtarlarının
// toplamından oluştuğunu gösteren eşleme. Resmi tablodaki gruplamalara birebir uyar.
const BA_DERS_MAP = {
  tytTurkce: ['tytTurkce'],
  tytSosyal: ['tytSosyal'],
  tytMat:    ['tytMatematik'],
  tytFen:    ['tytFen'],
  aytMat:       ['aytMatematik'],
  aytFizik:     ['aytFizik'],
  aytKimya:     ['aytKimya'],
  aytBiyoloji:  ['aytBiyoloji'],
  aytEdebiyat:  ['aytEdebiyat'],
  aytTarih1:    ['aytTarih1'],
  aytCografya1: ['aytCografya1'],
  aytTarih2:    ['aytTarih2'],
  aytCografya2: ['aytCografya2'],
  aytFelsefeGrubu: ['aytFelsefe'],
  aytDkab: ['aytDin'],
  ydt: ['ydtIngilizce']
};

// Genel amaçlı sütun+çizgi (combo) grafik — noktalar: [{etiket, deger}]
let baComboZoom = { denemeler: 1, brans: 1 };
function baRenderComboChart(noktalar, zoomKey, tikFn, birim) {
  if (!noktalar.length) {
    return `<div class="ba-empty">Henüz veri girilmedi.</div>`;
  }
  const birimEtiket = birim || 'Net';
  const zoom = baComboZoom[zoomKey] || 1;
  const genislikBirim = 40 * zoom;
  const w = Math.max(280, noktalar.length * genislikBirim);
  const tarihVar = noktalar.some(v => v.tarih);
  const h = tarihVar ? 176 : 160;
  const padTop = 16, padBottom = tarihVar ? 42 : 26, barW = Math.min(22, genislikBirim * 0.5);
  const maxVal = Math.max(...noktalar.map(v => v.deger), 1);
  const minVal = Math.min(...noktalar.map(v => v.deger), 0);
  const range = Math.max(maxVal - minVal, 1);
  const skalaY = (val) => padTop + (1 - (val - minVal) / range) * (h - padTop - padBottom);
  const pts = noktalar.map((v, i) => {
    const x = noktalar.length === 1 ? w/2 : (i / Math.max(1, noktalar.length - 1)) * (w - 30) + 15;
    return { x, y: skalaY(v.deger), taban: skalaY(minVal), ...v };
  });
  const cubuklar = pts.map(p => `
    <rect x="${(p.x - barW/2).toFixed(1)}" y="${Math.min(p.y, p.taban).toFixed(1)}" width="${barW}" height="${Math.abs(p.taban - p.y).toFixed(1)}"
      fill="url(#baBarGrad)" rx="5" style="cursor:pointer;" onclick="${tikFn}('${p.etiket}', ${p.deger}, '${birimEtiket}')"></rect>`).join('');
  const pathD = pts.map((p,i) => (i===0?'M':'L') + p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ');
  const noktaDaire = pts.map(p => `
    <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="4" fill="var(--accent)" style="cursor:pointer;" onclick="${tikFn}('${p.etiket}', ${p.deger}, '${birimEtiket}')"></circle>`).join('');
  const etiketler = pts.map(p => `
    <text x="${p.x.toFixed(1)}" y="${tarihVar ? h-22 : h-8}" font-size="9" fill="var(--text3)" text-anchor="middle">${p.etiket}</text>`).join('');
  // Etiketin altına (varsa) tarih: sütun genişliğine sığacak şekilde yazı boyutu otomatik ayarlanır
  // ("gg.aa" ≈ 2,5 em). Sütun payı = noktalar arası mesafe (tek nokta varsa tüm genişlik).
  const slot = noktalar.length === 1 ? w : (w - 30) / (noktalar.length - 1);
  const tarihFont = Math.max(5, Math.min(9, slot * 0.92 / 2.5));
  const tarihler = tarihVar ? pts.map(p => p.tarih ? `
    <text x="${p.x.toFixed(1)}" y="${h-8}" font-size="${tarihFont.toFixed(1)}" fill="var(--text3)" text-anchor="middle">${p.tarih}</text>` : '').join('') : '';
  // Her mumun/noktanın üzerinde değeri rakamsal olarak gösterir: Net ise olduğu gibi (ör. 46.25),
  // Puan ise sadece ilk 3 rakamı (tam sayı kısmı, ör. 367,128 -> 367) gösterilir.
  const degerMetni = (v) => {
    if (birimEtiket === 'Puan') return String(Math.trunc(v));
    return Number.isInteger(v) ? String(v) : String(Math.round(v * 100) / 100);
  };
  const degerEtiketleri = pts.map(p => `
    <text x="${p.x.toFixed(1)}" y="${Math.max(10, p.y - 8).toFixed(1)}" font-size="9" font-weight="700" fill="#3a2a15" text-anchor="middle">${degerMetni(p.deger)}</text>`).join('');

  return `
    <div class="ba-line-toolbar">
      <button class="ba-zoom-btn" onclick="baComboZoomChange('${zoomKey}', -1)">−</button>
      <button class="ba-zoom-btn" onclick="baComboZoomChange('${zoomKey}', 1)">+</button>
    </div>
    <div class="ba-line-scroll">
      <svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
        <defs>
          <linearGradient id="baBarGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#2dd4bf"/>
            <stop offset="100%" stop-color="#0f766e"/>
          </linearGradient>
        </defs>
        ${cubuklar}
        <path d="${pathD}" fill="none" stroke="var(--accent)" stroke-width="2"/>
        ${noktaDaire}
        ${degerEtiketleri}
        ${etiketler}
        ${tarihler}
      </svg>
    </div>
    <div class="ba-line-tooltip" id="baComboTooltip">Bir noktaya dokun, değeri gör</div>`;
}

function baComboZoomChange(key, delta) {
  baComboZoom[key] = Math.max(0.5, Math.min(3, (baComboZoom[key]||1) + delta * 0.25));
  renderGrafik();
}

function baComboTikGoster(etiket, deger, birim) {
  const el = document.getElementById('baComboTooltip');
  if (el) el.textContent = etiket + ' → ' + (birim || 'Net') + ': ' + deger;
}

// Bir (sınav, deneme no) için toplam net. onek: 'vgd_' = Veri Girişi > Denemeler, 'vgud_' = Denemelerim.
// HATA (düzeltildi): Eskiden VG_DERSLER (konu/ders listesi: tytGeometri, tytFizik...) kullanılıyordu; oysa
// deneme kayıtları DENEME_VG_DERSLER anahtarlarıyla (tytSosyal, tytFen, aytTarih1...) tutulur. Bu yüzden
// TYT'de Sosyal + Fen, AYT'de Tarih-1/2 + Coğrafya-1/2 netleri grafiğe hiç eklenmiyordu.
function baVgdDenemeNet(sinav, no, onek) {
  onek = onek || 'vgd_';
  const dersler = DENEME_VG_DERSLER[sinav] || [];
  let net = 0, anyData = false, sonTs = 0;
  dersler.forEach(d => {
    try {
      const s = JSON.parse(vgGetItem(onek + sinav + '_' + no + '_' + d.key) || '{}');
      const dd = +s.d || 0, yy = +s.y || 0, bb = +s.b || 0;
      if (dd || yy || bb) { anyData = true; net += dd - yy/4; }
      if (s.ts && s.ts > sonTs) sonTs = s.ts;
    } catch(e){}
  });
  return anyData ? { net: +net.toFixed(2), ts: sonTs } : null;
}

let baDenemeSinav = 'TYT';
function baSetDenemeSinav(s) { baDenemeSinav = s; renderGrafik(); }

// Bir sınav ("TYT"/"AYT"/"YDT") için hangi BA_KATSAYI puan türünün kullanılacağını belirler.
function baDenemeTurForSinav(sinav) {
  if (sinav === 'TYT') return 'TYT';
  if (sinav === 'YDT') return 'DIL';
  if (sinav === 'AYT') {
    const secili = baSinavListesiSecili();
    return secili.find(t => t === 'SAY' || t === 'EA' || t === 'SOZ') || null;
  }
  return null;
}

// Bir (sinav, no) denemesi için tahmini puan: taban + kategori netleri × katsayı + kendi OBP katkısı (×0.12)
function baDenemePuanHesapla(sinav, no, onek) {
  const tur = baDenemeTurForSinav(sinav);
  if (!tur) return null;
  const r = baVgdDenemeKategoriNet(sinav, no, tur, onek);
  if (!r) return null;
  const kat = BA_KATSAYI[tur];
  let puan = kat.taban;
  Object.keys(r.kategoriNet).forEach(k => { puan += r.kategoriNet[k] * (kat[k] || 0); });
  const obpKatkisi = baKendiObpKatkisi();
  if (obpKatkisi !== null) puan += obpKatkisi;
  return { puan: +puan.toFixed(2), ts: r.ts };
}

let baDenemeGorunum = 'net'; // 'net' | 'puan'
function baSetDenemeGorunum(g) { baDenemeGorunum = g; renderGrafik(); injectBackButton(); }

function baRenderDenemeler(el) {
  const sinav = baDenemeSinav;
  const gorunum = baDenemeGorunum;
  const noktalar = [];
  if (gorunum === 'net') {
    const vgNoktalar = [];
    for (let no = 1; no <= 30; no++) {
      const r = baVgdDenemeNet(sinav, no);
      if (r) vgNoktalar.push({ etiket: 'VG' + no, deger: r.net, ts: r.ts });
    }
    for (let no = 1; no <= DENEME_TOPLAM; no++) {
      const r = baVgdDenemeNet(sinav, no, 'vgud_');
      if (r) vgNoktalar.push({ etiket: denemeGrafikEtiket(no), deger: r.net, ts: r.ts });
    }
    vgNoktalar.sort((a, b) => a.ts - b.ts);
    noktalar.push(...vgNoktalar);
    if (sinav === 'TYT') {
      for (let no = 1; no <= TOPLAM_DENEME; no++) {
        const ozet = calcDenemeOzet(no);
        if (ozet.toplamNet !== null) noktalar.push({ etiket: 'Sis' + no, deger: +ozet.toplamNet });
      }
    }
  } else {
    const vgNoktalar = [];
    for (let no = 1; no <= 30; no++) {
      const r = baDenemePuanHesapla(sinav, no);
      if (r) vgNoktalar.push({ etiket: 'VG' + no, deger: r.puan, ts: r.ts });
    }
    for (let no = 1; no <= DENEME_TOPLAM; no++) {
      const r = baDenemePuanHesapla(sinav, no, 'vgud_');
      if (r) vgNoktalar.push({ etiket: denemeGrafikEtiket(no), deger: r.puan, ts: r.ts });
    }
    vgNoktalar.sort((a, b) => a.ts - b.ts);
    noktalar.push(...vgNoktalar);
  }

  const tabBtn = (s, ad) => `<button onclick="baSetDenemeSinav('${s}')" style="flex:1;padding:10px;border-radius:12px;cursor:pointer;font-size:0.82rem;font-weight:800;
    ${sinav===s ? 'background:linear-gradient(135deg,#8a6a2f,#d4af5a 60%,#b8903f);color:#3a2a15;border:none;box-shadow:0 4px 12px rgba(120,90,30,0.3);' : 'background:rgba(255,252,244,0.7);color:#6b5636;border:1px solid rgba(150,110,40,0.25);'}">${ad}</button>`;

  const gorunumBtn = (g, ad) => `<button onclick="baSetDenemeGorunum('${g}')" style="flex:1;padding:9px;border-radius:12px;cursor:pointer;font-size:0.78rem;font-weight:800;
    ${gorunum===g ? 'background:linear-gradient(135deg,#8a6a2f,#d4af5a 60%,#b8903f);color:#3a2a15;border:none;box-shadow:0 4px 12px rgba(120,90,30,0.3);' : 'background:rgba(255,252,244,0.7);color:#6b5636;border:1px solid rgba(150,110,40,0.25);'}">${ad}</button>`;

  const tur = baDenemeTurForSinav(sinav);
  const puanUyari = (gorunum === 'puan' && !tur) ? '<div style="font-size:0.72rem;color:#b3452e;margin-bottom:8px;">⚠️ Puan hesaplayabilmek için Kişisel Bilgilerim\'de "Hazırlanacağım Testler"i seç.</div>' : '';

  el.innerHTML = `
  <div class="fade-up" style="max-width:640px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 50% 0%,rgba(233,198,107,0.35),transparent 60%),linear-gradient(160deg,#fdf6e3,#f3e6c4);border:1px solid rgba(150,110,40,0.35);box-shadow:0 10px 26px rgba(0,0,0,0.18);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">
        <button onclick="baSetView(null)" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <img src="${BA_ICON_DENEMELER}" style="width:34px;height:34px;border-radius:8px;">
        <div style="font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:900;color:#3a2a15;">Denemelerim</div>
      </div>
      <div style="display:flex;gap:8px;margin-bottom:10px;">
        ${tabBtn('TYT','TYT')}${tabBtn('AYT','AYT')}${tabBtn('YDT','YDT')}
      </div>
      <div style="display:flex;gap:8px;margin-bottom:14px;">
        ${gorunumBtn('net','Netlere Göre')}${gorunumBtn('puan','Puana Göre')}
      </div>
      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:4px;">${sinav} DENEME ${gorunum === 'net' ? 'NETLERİ' : 'PUANLARI'} (ÇÖZÜLME SIRASINA GÖRE)</div>
        <div style="font-size:0.68rem;color:#8a7a5c;margin-bottom:8px;">${gorunum === 'net' ? "VG = Veri Girişi'nde girilen · UD = Denemelerim'de uygulamada çözülen · Sis = Denemeler sekmesinde sistemde çözülen" : 'VG = Veri Girişi · UD = Denemelerim · Puan = taban puan + net × katsayı + OBP × 0.12'}</div>
        ${puanUyari}
        ${baRenderComboChart(noktalar, 'denemeler', 'baComboTikGoster', gorunum === 'puan' ? 'Puan' : 'Net')}
      </div>
    </div>
  </div>`;
}

let baBransState = { test: null };
function baBransSetTest(key) { baBransState.test = key; renderGrafik(); injectBackButton(); }

function baRenderBransDenemeler(el) {
  if (!baBransState.test) {
    el.innerHTML = `
    <div class="fade-up" style="max-width:640px;margin:0 auto;">
      <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 50% 0%,rgba(233,198,107,0.35),transparent 60%),linear-gradient(160deg,#fdf6e3,#f3e6c4);border:1px solid rgba(150,110,40,0.35);box-shadow:0 10px 26px rgba(0,0,0,0.18);">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">
          <button onclick="baSetView(null)" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
          <img src="${BA_ICON_BRANS}" style="width:34px;height:34px;border-radius:8px;">
          <div style="font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:900;color:#3a2a15;">Branş Denemelerim</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:10px;">
          ${BRANS_TESTLER.map(t => `
          <div onclick="baBransSetTest('${t.key}')" style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:14px;padding:16px 14px;cursor:pointer;display:flex;align-items:center;gap:12px;">
            <div style="flex-shrink:0;width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,#8a6a2f,#d4af5a);display:flex;align-items:center;justify-content:center;font-size:1.1rem;">🎯</div>
            <span style="font-weight:800;font-size:0.88rem;flex:1;color:#3a2a15;">${t.ad}</span>
            <span style="color:#b8903f;font-size:1.1rem;">›</span>
          </div>`).join('')}
        </div>
      </div>
    </div>`;
    return;
  }

  const testObj = BRANS_TESTLER.find(t => t.key === baBransState.test);
  if (!testObj) { baBransSetTest(null); return; }

  const noktalar = [];
  for (let t = 1; t <= 50; t++) {
    try {
      const s = JSON.parse(vgGetItem('vgbd_' + testObj.key + '_0_' + t) || '{}');
      const dd = +s.d || 0, yy = +s.y || 0, bb = +s.b || 0;
      if (dd || yy || bb) noktalar.push({ etiket: String(t), deger: +(dd - yy/4).toFixed(2) });
    } catch(e){}
  }

  el.innerHTML = `
  <div class="fade-up" style="max-width:640px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 50% 0%,rgba(233,198,107,0.35),transparent 60%),linear-gradient(160deg,#fdf6e3,#f3e6c4);border:1px solid rgba(150,110,40,0.35);box-shadow:0 10px 26px rgba(0,0,0,0.18);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">
        <button onclick="baBransSetTest(null)" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <img src="${BA_ICON_BRANS}" style="width:34px;height:34px;border-radius:8px;">
        <div style="font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:900;color:#3a2a15;">${testObj.ad}</div>
      </div>
      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:8px;">BRANŞ DENEME NETLERİ (ÇÖZÜLME SIRASINA GÖRE)</div>
        ${baRenderComboChart(noktalar, 'brans', 'baComboTikGoster')}
      </div>
    </div>
  </div>`;
}

// Eski "Denemeler" sekmesindeki (state.denemeler, TYT) bir kaydın kategori net'leri
const BA_SIS_DENEME_KEY_MAP = { tytTurkce: 'tytTurkce', tytSosyal: 'tytSosyal', tytMat: 'tytMatematik', tytFen: 'tytFen' };
function baSisDenemeKategoriNet(no) {
  const den = (state.denemeler || {})[no];
  if (!den || !den.sonKayitTs) return null;
  const kategoriNet = {};
  let anyData = false;
  Object.keys(BA_SIS_DENEME_KEY_MAP).forEach(kat => {
    const dv = den.dersler[BA_SIS_DENEME_KEY_MAP[kat]];
    if (!dv) return;
    const dd = +dv.d || 0, yy = +dv.y || 0;
    if (dd || yy) { anyData = true; kategoriNet[kat] = dd - yy/4; }
  });
  return anyData ? { kategoriNet, ts: den.sonKayitTs } : null;
}

// Bir Veri Girişi denemesindeki (sinav, no) net'leri, belirli bir türün (BA_KATSAYI[tur]) kategori
// anahtarlarına göre topla
function baVgdDenemeKategoriNet(sinav, no, tur, onek) {
  onek = onek || 'vgd_';
  const alanlar = Object.keys(BA_KATSAYI[tur]).filter(k => k !== 'taban' && k !== 'eksikTaban');
  const kategoriNet = {};
  let anyData = false, sonTs = 0;
  alanlar.forEach(kat => {
    if (!BA_DERS_MAP[kat]) return;
    let toplam = 0, varMi = false;
    BA_DERS_MAP[kat].forEach(dKey => {
      try {
        const s = JSON.parse(vgGetItem(onek + sinav + '_' + no + '_' + dKey) || '{}');
        const dd = +s.d || 0, yy = +s.y || 0;
        if (dd || yy) { varMi = true; toplam += dd - yy/4; }
        if (s.ts && s.ts > sonTs) sonTs = s.ts;
      } catch(e){}
    });
    if (varMi) { anyData = true; kategoriNet[kat] = toplam; }
  });
  return anyData ? { kategoriNet, ts: sonTs } : null;
}

// Bir tür (TYT/SAY/EA/SOZ/DIL) hangi Veri Girişi sınavından besleniyor
const BA_TUR_VG_SINAV = { TYT: 'TYT', SAY: 'AYT', EA: 'AYT', SOZ: 'AYT', DIL: 'YDT' };

// ── Hedefime Yaklaşma Oranım ─────────────────────────────────
// Kişisel Bilgilerim'deki 2026 katsayı tablosu ve OBP formülleriyle aynı mantık kullanılır.
function baKullaniciPuaniTur(tur) {
  const sinav = BA_TUR_VG_SINAV[tur];
  const kayitlar = [];
  for (let no = 1; no <= 30; no++) {
    const r = baVgdDenemeKategoriNet(sinav, no, tur);
    if (r && r.ts) kayitlar.push({ kaynak: 'vg', sinav, no, ts: r.ts, kategoriNet: r.kategoriNet });
  }
  for (let no = 1; no <= DENEME_TOPLAM; no++) {
    const r = baVgdDenemeKategoriNet(sinav, no, tur, 'vgud_');
    if (r && r.ts) kayitlar.push({ kaynak: 'ud', sinav, no, ts: r.ts, kategoriNet: r.kategoriNet });
  }
  if (tur === 'TYT') {
    for (let no = 1; no <= TOPLAM_DENEME; no++) {
      const r = baSisDenemeKategoriNet(no);
      if (r) kayitlar.push({ kaynak: 'sis', sinav: 'TYT', no, ts: r.ts, kategoriNet: r.kategoriNet });
    }
  }
  kayitlar.sort((a,b) => b.ts - a.ts);
  const son3 = kayitlar.slice(0, 3);
  if (!son3.length) return null;

  const kat = BA_KATSAYI[tur];
  const obpKatkisi = baKendiObpKatkisi();

  const puanlar = son3.map(kayit => {
    let puan = kat.taban;
    Object.keys(kayit.kategoriNet).forEach(k => { puan += kayit.kategoriNet[k] * (kat[k] || 0); });
    if (obpKatkisi !== null) puan += obpKatkisi;
    return puan;
  });

  const ortalama = puanlar.reduce((a,b) => a+b, 0) / puanlar.length;

  // Ders bazlı kıyaslama için: sadece son deneme değil, kayıtlı son (en fazla) 3 denemenin ortalama neti kullanılır.
  const ortalamaKategoriNet = {};
  const kategoriSayac = {};
  son3.forEach(kayit => {
    Object.keys(kayit.kategoriNet).forEach(k => {
      ortalamaKategoriNet[k] = (ortalamaKategoriNet[k] || 0) + kayit.kategoriNet[k];
      kategoriSayac[k] = (kategoriSayac[k] || 0) + 1;
    });
  });
  Object.keys(ortalamaKategoriNet).forEach(k => { ortalamaKategoriNet[k] = ortalamaKategoriNet[k] / kategoriSayac[k]; });

  return { ortalama, sonDeneme: son3[0], ortalamaKategoriNet, kayitSayisi: son3.length };
}

function baSinavListesiSecili() {
  const testler = (state.kisisel && state.kisisel.testler) || [];
  return Array.from(new Set(testler.map(t => BA_TEST_TUR[t]).filter(Boolean))); // ["TYT","SAY",...]
}

function baKatAdi(kat) {
  return ({
    tytTurkce:'TYT Türkçe', tytSosyal:'TYT Sosyal', tytMat:'TYT Matematik', tytFen:'TYT Fen',
    aytMat:'AYT Matematik', aytFizik:'AYT Fizik', aytKimya:'AYT Kimya', aytBiyoloji:'AYT Biyoloji',
    aytEdebiyat:'AYT Edebiyat', aytTarih1:'AYT Tarih-1', aytCografya1:'AYT Coğrafya-1',
    aytTarih2:'AYT Tarih-2', aytCografya2:'AYT Coğrafya-2', aytFelsefeGrubu:'AYT Felsefe Grubu',
    aytDkab:'AYT DKAB/İlave Felsefe',
    ydt:'YDT'
  })[kat] || kat;
}

function baRenderHedefYaklasmaTur(tur) {
  const netler = (state.kisisel && state.kisisel.netler) || {};
  const hedef = kbHedefPuanHesaplaTur(tur, netler);
  const kullanici = baKullaniciPuaniTur(tur);

  let yuzdeHtml;
  if (hedef.girisSayisi === 0 || !kullanici) {
    yuzdeHtml = `<div style="font-size:1.1rem;font-weight:900;color:#8a7a5c;">Yeterli veri bekleniyor</div>
      <div style="font-size:0.72rem;color:#8a7a5c;margin-top:4px;">
        ${hedef.girisSayisi === 0 ? 'Kişisel Bilgilerim\'de bu türle ilgili hedef netleri/OBP\'yi gir. ' : ''}
        ${!kullanici ? 'Veri Girişi\'nde bu türle ilgili en az 1 deneme sonucu gir.' : ''}
      </div>`;
  } else {
    const yuzde = hedef.toplam > 0 ? Math.min(999, Math.round(kullanici.ortalama / hedef.toplam * 100)) : 0;
    const renk = yuzde >= 90 ? '#178a4c' : yuzde >= 60 ? '#b8903f' : '#b3452e';
    yuzdeHtml = `<div style="font-size:2.3rem;font-weight:900;color:${renk};">%${yuzde}</div>
      <div style="font-size:0.72rem;color:#8a7a5c;margin-top:4px;">
        Hedef puan: ${hedef.toplam.toFixed(1)} · Son ${kullanici.kayitSayisi} deneme ortalaman: ${kullanici.ortalama.toFixed(1)}
        ${hedef.eksikTaban ? '<br><strong style="color:#b3452e;">⚠️ Bu tür için taban puan eksik, sonuç eksik olabilir.</strong>' : ''}
      </div>`;
  }

  // Ders ders net kıyaslaması: hedef netler vs. en son deneme netleri — türe ait TÜM dersler listelenir
  let dersKiyasHtml = '';
  if (kullanici) {
    const ortalamaKategoriNet = kullanici.ortalamaKategoriNet || {};
    const alanlar = Object.keys(BA_KATSAYI[tur]).filter(k => k !== 'taban' && k !== 'eksikTaban');
    const satirlar = alanlar.map(kat => {
      const hedefNetRaw = netler[kat];
      const hedefNet = parseFloat(hedefNetRaw);
      const hedefVar = !isNaN(hedefNet) && hedefNetRaw !== '' && hedefNetRaw !== undefined;
      const kullaniciNet = ortalamaKategoriNet[kat] !== undefined ? ortalamaKategoriNet[kat] : null;

      let pctHtml, netHtml, renk = '#8a7a5c';
      if (hedefVar && kullaniciNet !== null) {
        const pct = hedefNet > 0 ? Math.min(999, Math.round(kullaniciNet / hedefNet * 100)) : 0;
        renk = pct >= 90 ? '#178a4c' : pct >= 60 ? '#b8903f' : '#b3452e';
        pctHtml = '%' + pct;
        netHtml = kullaniciNet.toFixed(1) + ' / ' + hedefNet.toFixed(1) + ' net';
      } else {
        pctHtml = '—';
        netHtml = (kullaniciNet !== null ? kullaniciNet.toFixed(1) : '—') + ' / ' + (hedefVar ? hedefNet.toFixed(1) : '—') + ' net';
      }
      return `
        <div style="display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid rgba(150,110,40,0.15);">
          <span style="flex:1;font-size:0.82rem;font-weight:700;color:#3a2a15;">${baKatAdi(kat)}</span>
          <span style="font-size:0.72rem;color:#8a7a5c;">${netHtml}</span>
          <span style="font-size:0.82rem;font-weight:900;color:${renk};min-width:44px;text-align:right;">${pctHtml}</span>
        </div>`;
    }).join('');

    dersKiyasHtml = `
      <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;margin-top:12px;">
        <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:8px;">DERS DERS NET KIYASLAMASI (SON 3 DENEME ORTALAMASI)</div>
        ${satirlar}
        <div style="font-size:0.68rem;color:#8a7a5c;margin-top:8px;">"—" görünen alanlar için Kişisel Bilgilerim'de hedef net gir veya Veri Girişi'nde o dersten deneme sonucu ekle.</div>
      </div>`;
  }

  return `
    <div style="background:rgba(255,252,244,0.85);border:1px solid rgba(150,110,40,0.25);border-radius:16px;padding:16px;text-align:center;">
      <div style="font-size:0.72rem;font-weight:800;letter-spacing:0.5px;color:#8a6a2f;margin-bottom:10px;">${BA_TUR_AD[tur]} — YAKLAŞMA YÜZDEM</div>
      ${yuzdeHtml}
    </div>
    ${dersKiyasHtml}`;
}

