function kvKonular(d) {
  if (d.vgKey === 'ydtIngilizce') return YDT_INGILIZCE_KONU_BASLIKLARI;
  if (d.vgKey) {
    const vgD = sbVgDersByKey(d.vgKey);
    if (vgD) return vgD.kazanimlar;
  }
  if (d.konular) return d.konular;
  return (DERSLER[d.key] && DERSLER[d.key].kazanimlar) || [];
}
