function renderSayacAyarSure(el, tip) {
  const ayar = sayacAyarOku();
  const mevcutMs = tip === 'ders' ? ayar.dersMs : ayar.molaMs;
  const saatSec = Math.floor(mevcutMs / 3600000);
  const dkSec = Math.round((mevcutMs % 3600000) / 60000);
  const saatSecenek = [0, 1, 2, 3].map(s => `<option value="${s}" ${s === saatSec ? 'selected' : ''}>${s} saat</option>`).join('');
  const dkListesi = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55];
  const dkSecenek = dkListesi.map(m => `<option value="${m}" ${m === dkSec ? 'selected' : ''}>${m} dk</option>`).join('');
  const baslik = tip === 'ders' ? '⏱️ Ders Süresini Ayarla' : '☕ Mola Süresini Ayarla';
  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">
        <button onclick="sayacSt.view='ayarlar';renderDersSayaci(document.getElementById('mainContent'));" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:900;color:#3a2a15;">${baslik}</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">Saat ve dakika seç</div>
        </div>
      </div>
      <div style="display:flex;gap:12px;margin-bottom:18px;">
        <select id="sayacAyarSaat" style="flex:1;padding:12px;border-radius:12px;border:1px solid rgba(180,140,60,0.35);background:rgba(255,253,247,0.9);font-size:0.95rem;font-weight:700;color:#3a2a15;">${saatSecenek}</select>
        <select id="sayacAyarDk" style="flex:1;padding:12px;border-radius:12px;border:1px solid rgba(180,140,60,0.35);background:rgba(255,253,247,0.9);font-size:0.95rem;font-weight:700;color:#3a2a15;">${dkSecenek}</select>
      </div>
      <button onclick="sayacAyarlarKaydet('${tip}')" style="width:100%;padding:13px;border-radius:14px;border:none;cursor:pointer;background:linear-gradient(135deg,#8a6a2f,#d4af5a 60%,#b8903f);color:#3a2a15;font-weight:900;font-size:0.92rem;box-shadow:0 4px 12px rgba(120,90,30,0.3);">Kaydet</button>
    </div>
  </div>`;
}


