//  📰 HABERLER & DUYURULAR
// ============================================================
function renderHaberlerDuyurular(el) {
  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">
        <button onclick="switchToTab('dashboard')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;color:#3a2a15;">📰 Haberler ve Duyurular</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">YKS Pusulam'dan güncel bilgiler</div>
        </div>
      </div>
      <div style="background:rgba(255,253,247,0.75);border:1px solid rgba(180,140,60,0.25);border-radius:14px;padding:24px 16px;text-align:center;">
        <div style="font-size:2rem;margin-bottom:8px;">🕊️</div>
        <div style="font-weight:700;font-size:0.9rem;color:#3a2a15;margin-bottom:6px;">Henüz bir duyuru yok</div>
        <div style="font-size:0.8rem;color:#6b5636;line-height:1.5;">Yeni haberler ve duyurular yayınlandığında burada görünecek. Takipte kal!</div>
      </div>
    </div>
  </div>`;
}

// Konu adının sonundaki açıklayıcı parantez ifadesini temizler.
// Örn: "Fonksiyonlar (fonksiyon kavramı, gösterimi / ...)" -> "Fonksiyonlar"
function yilDagilimKonuTemizle(konu) {
  return (konu || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
}

function renderYillaraGoreSoruDagilimi(el) {
  const geriTab = () => yilDagilimUI.ders ? 'yilDagilimGeriListe()' : "switchToTab('yksNedir')";
  const headerHtml = (baslik2, alt2) => `
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">
        <button onclick="${geriTab()}" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.3rem;font-weight:900;color:#3a2a15;">📈 ${baslik2}</div>
          ${alt2 ? `<div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">${alt2}</div>` : ''}
        </div>
      </div>`;

  if (!yilDagilimUI.ders) {
    const dersKart = (d) => `
      <div onclick="yilDagilimSecDers('${d.key}')" style="cursor:pointer;display:flex;align-items:center;gap:10px;background:rgba(255,253,247,0.85);border:1px solid rgba(180,140,60,0.25);border-radius:12px;padding:10px 12px;margin-bottom:8px;">
        <div style="flex-shrink:0;width:38px;height:38px;border-radius:10px;background:${d.grad || 'linear-gradient(135deg,#8a6a2f,#d4af5a)'};display:flex;align-items:center;justify-content:center;font-size:1.1rem;">${d.emoji || '📘'}</div>
        <div style="flex:1;font-weight:700;font-size:0.85rem;color:#3a2a15;">${d.ad}</div>
        <div style="color:#b8903f;font-size:1.1rem;">›</div>
      </div>`;
    const grupBaslik = (t) => `<div style="font-weight:800;font-size:0.88rem;margin:16px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#d4af5a,#8a6a2f);border-radius:2px;"></span>${t}</div>`;
    const renkliListe = (gruplar) => gruplar.map(g => g.anahtarlar.map(anahtar => {
      const bilgi = yilDagilimDersBilgi(anahtar);
      return dersKart(Object.assign({}, bilgi, { grad: g.grad }));
    }).join('')).join('');

    el.innerHTML = `
    <div class="fade-up" style="max-width:560px;margin:0 auto;">
      <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
        ${headerHtml('Yıllara Göre Soru Dağılımı','İncelemek istediğin dersi seç')}
        ${grupBaslik('📋 TYT Dersleri')}
        ${renkliListe(YIL_DAGILIM_TYT_GRUPLAR)}
        ${grupBaslik('📋 AYT Dersleri')}
        ${renkliListe(YIL_DAGILIM_AYT_GRUPLAR)}
        ${grupBaslik('📋 YDT')}
        ${(VG_DERSLER.YDT || []).map(dersKart).join('')}
        <div style="font-size:0.68rem;color:#8a7a5c;margin-top:12px;line-height:1.5;">ℹ️ Dağılımlar, uygulama içindeki soru bankasına eklenmiş gerçek çıkmış sorulardan otomatik olarak hesaplanır.</div>
      </div>
    </div>`;
    return;
  }

  const dersKey = yilDagilimUI.ders;
  const bilgi = yilDagilimDersBilgi(dersKey);
  const sorular = SORULAR.filter(s => (s.dagilimDers || s.ders) === dersKey);
  const yilRegex = /^(\d{4})-/;
  const yillarSet = {};
  const dagilim = {};
  sorular.forEach(s => {
    const m = (s.kaynak || '').match(yilRegex);
    if (!m) return;
    const yil = m[1];
    yillarSet[yil] = true;
    const konu = yilDagilimKonuTemizle(s.konu) || 'Diğer';
    if (!dagilim[konu]) dagilim[konu] = {};
    dagilim[konu][yil] = (dagilim[konu][yil] || 0) + 1;
  });
  const yillar = Object.keys(yillarSet).sort();

  let konuSirali = (bilgi.kazanimlar || []).map(yilDagilimKonuTemizle);
  Object.keys(dagilim).forEach(k => { if (konuSirali.indexOf(k) === -1) konuSirali.push(k); });
  // Aynı temizlenmiş isimde tekrar oluşmuşsa tekilleştir
  konuSirali = konuSirali.filter((k, i) => konuSirali.indexOf(k) === i);

  const konuKolonGenislik = 118;
  const tabloGenislik = konuKolonGenislik + (yillar.length * 44);

  let tabloHtml;
  if (yillar.length === 0) {
    tabloHtml = `<div style="padding:24px 12px;text-align:center;color:#8a7a5c;font-size:0.82rem;">Bu ders için soru bankasında henüz yıl bilgisi içeren çıkmış soru bulunmuyor.</div>`;
  } else {
    const basliklar = yillar.map(y => `<th style="padding:8px 4px;text-align:center;width:44px;font-size:0.68rem;">${y}</th>`).join('');
    const satirlar = konuSirali.map((konu, i) => {
      const row = dagilim[konu] || {};
      const bg = i % 2 ? 'rgba(255,253,247,0.7)' : 'rgba(240,232,212,0.55)';
      const hucreler = yillar.map(y => {
        const c = row[y] || 0;
        return `<td style="padding:6px 2px;text-align:center;background:${bg};color:${c ? '#3a2a15' : '#c9bda0'};font-size:0.7rem;">${c || '–'}</td>`;
      }).join('');
      return `<tr>
        <td style="padding:6px 8px;font-weight:700;font-size:0.68rem;color:#3a2a15;background:${bg};position:sticky;left:0;width:${konuKolonGenislik}px;max-width:${konuKolonGenislik}px;white-space:normal;word-break:break-word;line-height:1.25;vertical-align:middle;">${konu}</td>
        ${hucreler}
      </tr>`;
    }).join('');
    tabloHtml = `
      <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;border:1px solid rgba(180,140,60,0.3);border-radius:12px;margin-top:6px;">
        <table style="border-collapse:collapse;width:100%;min-width:${tabloGenislik}px;table-layout:fixed;">
          <thead>
            <tr style="background:linear-gradient(135deg,#8a6a2f,#d4af5a);color:#fff;">
              <th style="padding:8px 8px;text-align:left;position:sticky;left:0;background:#8a6a2f;width:${konuKolonGenislik}px;font-size:0.68rem;">Konu</th>
              ${basliklar}
            </tr>
          </thead>
          <tbody>${satirlar}</tbody>
        </table>
      </div>
      <div style="font-size:0.66rem;color:#8a7a5c;margin-top:8px;">📱 Tabloyu tam görmek için telefonunu yan çevirebilir ya da yatay kaydırabilirsin.</div>`;
  }

  el.innerHTML = `
  <div class="fade-up" style="max-width:640px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      ${headerHtml(bilgi.emoji + ' ' + bilgi.ad, '')}
      ${tabloHtml}
    </div>
  </div>`;
}

// ============================================================
//  🧮 YKS PUAN HESAPLAMA (yaklaşık)
// ============================================================
function renderPuanHesaplama(el) {
  const k = (state.kisisel && state.kisisel.phObp) || '';
  if (!state.kisisel) state.kisisel = { netler: {} };
  const ph = state.kisisel.phNetler || {};
  const numInp = (id, label, key) => `
    <div style="display:flex;flex-direction:column;gap:4px;">
      <label style="font-size:0.68rem;color:#6b5636;font-weight:700;">${label}</label>
      <input autocomplete="off" type="number" step="0.25" id="${id}" value="${ph[key] || ''}" placeholder="0" oninput="phSave()" style="padding:9px 10px;border:1px solid rgba(180,140,60,0.4);border-radius:10px;font-size:0.85rem;width:100%;background:rgba(255,253,247,0.85);color:#3a2a15;">
    </div>`;
  const baslik = (t) => `<div style="font-weight:800;font-size:0.9rem;margin:16px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#d4af5a,#8a6a2f);border-radius:2px;"></span>${t}</div>`;
  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">
        <button onclick="switchToTab('yksNedir')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;color:#3a2a15;">🧮 YKS Puan Hesaplama</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">Netlerini gir, yaklaşık puanını gör</div>
        </div>
      </div>
      ${baslik('TYT Netleri')}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        ${numInp('ph_tur','Türkçe (40)','tur')}${numInp('ph_sos','Sosyal Bilimler (20)','sos')}
        ${numInp('ph_mat','Temel Matematik (40)','mat')}${numInp('ph_fen','Fen Bilimleri (20)','fen')}
      </div>
      ${baslik('AYT Netleri')}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        ${numInp('ph_amat','Matematik (40)','amat')}${numInp('ph_aed','Edebiyat-Sosyal Bil. 1 (40)','aed')}
        ${numInp('ph_afen','Fen Bilimleri (40)','afen')}${numInp('ph_asos','Sosyal Bilimler 2 (40)','asos')}
      </div>
      ${baslik('Diğer')}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        ${numInp('ph_ydt','YDT Yabancı Dil (80)','ydt')}
        <div style="display:flex;flex-direction:column;gap:4px;">
          <label style="font-size:0.68rem;color:#6b5636;font-weight:700;">Diploma Notu (100 üzerinden)</label>
          <input autocomplete="off" type="number" id="ph_obp" value="${k}" placeholder="Örn: 85" oninput="phSave()" style="padding:9px 10px;border:1px solid rgba(180,140,60,0.4);border-radius:10px;font-size:0.85rem;width:100%;background:rgba(255,253,247,0.85);color:#3a2a15;">
        </div>
      </div>
      <button style="width:100%;margin-top:18px;padding:13px;border:none;border-radius:14px;font-weight:800;font-size:0.9rem;cursor:pointer;background:linear-gradient(135deg,#8a6a2f,#d4af5a 50%,#b8903f);color:#2b2008;box-shadow:0 4px 12px rgba(120,90,30,0.3);" onclick="phHesapla()">🧮 Hesapla</button>
      <div id="phSonuc" style="margin-top:16px;">${Object.keys(ph).length ? phSonucHtml() : ''}</div>
      <div style="font-size:0.66rem;color:#8a7a5c;margin-top:12px;">⚠️ Bu hesaplama yaklaşık katsayılarla yapılır; ÖSYM'nin resmi puanı, sınavın o yılki standart sapmasına göre değişir. Kesin sonuç için ÖSYM hesaplayıcılarını da kontrol et.</div>
    </div>
  </div>`;
}
function phSave() {
  if (!state.kisisel) state.kisisel = { netler: {} };
  const g = id => (document.getElementById(id) || {}).value || '';
  state.kisisel.phNetler = {
    tur: g('ph_tur'), sos: g('ph_sos'), mat: g('ph_mat'), fen: g('ph_fen'),
    amat: g('ph_amat'), aed: g('ph_aed'), afen: g('ph_afen'), asos: g('ph_asos'), ydt: g('ph_ydt')
  };
  state.kisisel.phObp = g('ph_obp');
  saveState();
}
// Girilen TYT/AYT netlerinden tüm puan türlerini hesaplar (Puan Hesaplama ekranı ve Genel Durumum ortak kullanır)
function phHesaplaTumTurler(n, obpYuzluk) {
  const g = (v) => parseFloat(v) || 0;
  const tur = g(n.tur), sos = g(n.sos), mat = g(n.mat), fen = g(n.fen);
  const amat = g(n.amat), aed = g(n.aed), afen = g(n.afen), asos = g(n.asos), ydt = g(n.ydt);
  const obp = Math.min(100, g(obpYuzluk)) * 5 * 0.12;
  const tytHam = 100 + tur * 3.3 + sos * 3.4 + mat * 3.3 + fen * 3.4;
  const tytKat = tur * 1.32 + sos * 1.36 + mat * 1.32 + fen * 1.36;
  const say = 100 + tytKat + amat * 3.0 + afen * 2.8;
  const ea  = 100 + tytKat + amat * 3.0 + aed * 3.0;
  const soz = 100 + tytKat + aed * 3.0 + asos * 2.9;
  const dil = 100 + tytKat + ydt * 3.0;
  return {
    TYT: tytHam + obp, SAY: say + obp, EA: ea + obp, SOZ: soz + obp, DIL: dil + obp,
    hamlar: { TYT: tytHam, SAY: say, EA: ea, SOZ: soz, DIL: dil }, obp
  };
}
function phSonucHtml() {
  const n = state.kisisel.phNetler || {};
  const sonuc = phHesaplaTumTurler(n, state.kisisel.phObp);
  const row = (ad, tur) => `
    <div style="display:flex;justify-content:space-between;align-items:center;background:rgba(255,253,247,0.75);border:1px solid rgba(180,140,60,0.25);border-radius:12px;padding:10px 12px;margin-bottom:8px;">
      <div style="font-size:0.85rem;color:#3a2a15;font-weight:700;">${ad}</div>
      <div style="text-align:right;">
        <div style="font-weight:900;color:#8a6a2f;font-size:1.05rem;">${sonuc[tur].toFixed(2)}</div>
        <div style="font-size:0.65rem;color:#8a7a5c;">Ham: ${sonuc.hamlar[tur].toFixed(2)} + OBP: ${sonuc.obp.toFixed(1)}</div>
      </div>
    </div>`;
  return row('TYT Puanı','TYT') + row('SAY Puanı','SAY') + row('EA Puanı','EA') + row('SÖZ Puanı','SOZ') + row('DİL Puanı','DIL');
}
function phHesapla() {
  phSave();
  document.getElementById('phSonuc').innerHTML = phSonucHtml();
}